// CONFIGURAÇÕES PRINCIPAIS
// ==========================================================

// A planilha-base deixa de ter ID fixo.
// Na primeira instalação, instalarSistemaHoraAtividade()
// grava automaticamente o ID da cópia atual nas propriedades
// do projeto. Isso permite copiar o aplicativo para outro Drive.
const CHAVE_ID_PLANILHA_BASE =
  "HORA_ATIVIDADE_PLANILHA_BASE_ID";

// Este valor é substituído automaticamente pelo instalador web
