function garantirEstruturaMunicipal_() {

  const ss =
    getPlanilhaBase();

  let abaUnidades =
    ss.getSheetByName(
      ABA_UNIDADES
    );

  if (!abaUnidades) {
    abaUnidades =
      ss.insertSheet(
        ABA_UNIDADES
      );
  }

  if (
    abaUnidades.getLastRow() === 0
  ) {
    abaUnidades.appendRow([
      "ID",
      "TIPO",
      "UNIDADE ESCOLAR",
      "ATIVO"
    ]);
  }

  if (
    abaUnidades.getLastRow() === 1
  ) {
    let id = 1;

    UNIDADES_OFICIAIS_LONDRINA
      .forEach(
        function(item) {
          abaUnidades.appendRow([
            id++,
            item.tipo,
            item.nome,
            "SIM"
          ]);
        }
      );
  }

  const abaUsuarios =
    ss.getSheetByName(
      ABA_USUARIOS
    );

  if (abaUsuarios) {
    abaUsuarios
      .getRange(1, COL_USUARIO_UNIDADE_ID)
      .setValue("UNIDADE_ID");
  }

  const abaProf =
    ss.getSheetByName(
      ABA_PROFESSORES
    );

  if (abaProf) {
    abaProf
      .getRange(1, COL_PROFESSOR_UNIDADE_ID)
      .setValue("UNIDADE_ID");
  }

  return {
    sucesso: true
  };

}


function instalarEstruturaMunicipal() {

  garantirEstruturaMunicipal_();

  const ss =
    getPlanilhaBase();

  const abaUnidades =
    ss.getSheetByName(
      ABA_UNIDADES
    );

  const ultimaUnidade =
    abaUnidades.getLastRow();

  const unidades =
    ultimaUnidade >= 2
      ? abaUnidades
          .getRange(
            2,
            1,
            ultimaUnidade - 1,
            4
          )
          .getValues()
      : [];

  let unidadeNaraId = "";

  unidades.forEach(
    function(linha) {
      if (
        String(linha[2] || "")
          .trim()
          .toUpperCase() ===
        "ESCOLA MUNICIPAL NARA MANELLA"
      ) {
        unidadeNaraId =
          linha[0];
      }
    }
  );

  // Migração segura da escola que já usa o sistema hoje:
  // registros antigos sem UNIDADE_ID são vinculados à Nara Manella.
  if (unidadeNaraId) {

    const abaProf =
      ss.getSheetByName(
        ABA_PROFESSORES
      );

    if (
      abaProf &&
      abaProf.getLastRow() >= 2
    ) {

      const qtd =
        abaProf.getLastRow() - 1;

      const ids =
        abaProf
          .getRange(
            2,
            COL_PROFESSOR_UNIDADE_ID,
            qtd,
            1
          )
          .getValues();

      for (
        let i = 0;
        i < ids.length;
        i++
      ) {
        if (!ids[i][0]) {
          abaProf
            .getRange(
              i + 2,
              COL_PROFESSOR_UNIDADE_ID
            )
            .setValue(
              unidadeNaraId
            );
        }
      }
    }

    const abaUsuarios =
      ss.getSheetByName(
        ABA_USUARIOS
      );

    if (
      abaUsuarios &&
      abaUsuarios.getLastRow() >= 2
    ) {

      const qtd =
        abaUsuarios.getLastRow() - 1;

      const dados =
        abaUsuarios
          .getRange(
            2,
            1,
            qtd,
            COL_USUARIO_UNIDADE_ID
          )
          .getValues();

      dados.forEach(
        function(linha, indice) {

          const tipo =
            String(
              linha[4] || ""
            )
              .trim()
              .toUpperCase();

          const unidadeAtual =
            linha[
              COL_USUARIO_UNIDADE_ID - 1
            ];

          if (
            tipo === "PROFESSOR" &&
            !unidadeAtual
          ) {
            abaUsuarios
              .getRange(
                indice + 2,
                COL_USUARIO_UNIDADE_ID
              )
              .setValue(
                unidadeNaraId
              );
          }

        }
      );
    }
  }

  SpreadsheetApp.flush();

  return {
    sucesso: true,
    mensagem:
      "Estrutura municipal instalada. Professores antigos sem unidade foram vinculados à Escola Municipal Nara Manella."
  };

}


function buscarUnidadePorId_(
  unidadeId
) {

  garantirEstruturaMunicipal_();

  const ss =
    getPlanilhaBase();

  const aba =
    ss.getSheetByName(
      ABA_UNIDADES
    );

  if (
    !aba ||
    aba.getLastRow() < 2
  ) {
    return null;
  }

  const dados =
    aba
      .getRange(
        2,
        1,
        aba.getLastRow() - 1,
        4
      )
      .getValues();

  for (
    let i = 0;
    i < dados.length;
    i++
  ) {

    if (
      String(dados[i][0]) ===
      String(unidadeId)
    ) {
      return {
        id: dados[i][0],
        tipo: String(dados[i][1] || ""),
        nome: String(dados[i][2] || ""),
        ativo:
          String(dados[i][3] || "")
            .trim()
            .toUpperCase()
      };
    }
  }

  return null;

}


function listarUnidades(
  token
) {

  try {

    const sessao =
      validarSessao(
        token
      );

    if (
      !sessao.valido ||
      !["ADMIN", "DIRETOR"]
        .includes(
          sessao.usuario.tipo
        )
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }

    garantirEstruturaMunicipal_();

    const ss =
      getPlanilhaBase();

    const aba =
      ss.getSheetByName(
        ABA_UNIDADES
      );

    const dados =
      aba
        .getRange(
          2,
          1,
          Math.max(
            aba.getLastRow() - 1,
            0
          ),
          4
        )
        .getValues();

    let unidades =
      dados
        .filter(
          function(linha) {
            return (
              linha[0] &&
              String(linha[3] || "")
                .trim()
                .toUpperCase() ===
              "SIM"
            );
          }
        )
        .map(
          function(linha) {
            return {
              id: linha[0],
              tipo: String(linha[1] || ""),
              nome: String(linha[2] || "")
            };
          }
        );

    if (
      sessao.usuario.tipo ===
      "DIRETOR"
    ) {
      unidades =
        unidades.filter(
          function(item) {
            return (
              String(item.id) ===
              String(
                sessao.usuario.unidadeId
              )
            );
          }
        );
    }

    unidades.sort(
      function(a, b) {
        if (a.tipo !== b.tipo) {
          return a.tipo.localeCompare(
            b.tipo,
            "pt-BR"
          );
        }
        return a.nome.localeCompare(
          b.nome,
          "pt-BR"
        );
      }
    );

    return {
      sucesso: true,
      unidades: unidades
    };

  } catch (erro) {

    return {
      sucesso: false,
      mensagem:
        erro.message
    };

  }

}


function obterUnidadePermitida_(
  sessao,
  unidadeId
) {

  if (
    !sessao ||
    !sessao.valido
  ) {
    throw new Error(
      "Sessão expirada."
    );
  }

  const tipo =
    sessao.usuario.tipo;

  if (
    tipo === "DIRETOR"
  ) {
    unidadeId =
      sessao.usuario.unidadeId;
  }

  if (
    tipo === "ADMIN" &&
    !unidadeId
  ) {
    throw new Error(
      "Selecione a unidade escolar."
    );
  }

  if (
    !["ADMIN", "DIRETOR"]
      .includes(tipo)
  ) {
    throw new Error(
      "Acesso não autorizado."
    );
  }

  const unidade =
    buscarUnidadePorId_(
      unidadeId
    );

  if (
    !unidade ||
    unidade.ativo !== "SIM"
  ) {
    throw new Error(
      "Unidade escolar inválida ou inativa."
    );
  }

  if (
    tipo === "DIRETOR" &&
    String(unidade.id) !==
    String(
      sessao.usuario.unidadeId
    )
  ) {
    throw new Error(
      "Acesso não autorizado a esta unidade."
    );
  }

  return unidade;

}


function usuarioPertenceUnidade_(
  usuarioId,
  unidadeId
) {

  const ss =
    getPlanilhaBase();

  const aba =
    ss.getSheetByName(
      ABA_USUARIOS
    );

  if (
    !aba ||
    aba.getLastRow() < 2
  ) {
    return false;
  }

  const dados =
    aba
      .getRange(
        2,
        1,
        aba.getLastRow() - 1,
        COL_USUARIO_UNIDADE_ID
      )
      .getValues();

  return dados.some(
    function(linha) {
      return (
        String(linha[0]) ===
        String(usuarioId) &&
        String(
          linha[
            COL_USUARIO_UNIDADE_ID - 1
          ]
        ) ===
        String(unidadeId)
      );
    }
  );

}



