function concluirPrimeiroAcessoAdmin(
  token,
  novoEmail,
  novaSenha
) {

  try {

    const sessao =
      validarSessao(
        token
      );


    if (
      !sessao.valido ||
      sessao.usuario.tipo !==
        "ADMIN"
    ) {

      throw new Error(
        "Acesso não autorizado."
      );

    }


    novoEmail =
      String(
        novoEmail || ""
      ).trim();


    novaSenha =
      String(
        novaSenha || ""
      );


    if (
      !emailValido_(
        novoEmail
      )
    ) {

      throw new Error(
        "Informe um e-mail válido."
      );

    }


    if (
      novaSenha.length < 6
    ) {

      throw new Error(
        "A nova senha deve ter pelo menos 6 caracteres."
      );

    }


    const ss =
      getPlanilhaBase();


    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    if (!aba) {

      throw new Error(
        "Aba USUÁRIOS não encontrada."
      );

    }


    const ultimaLinha =
      aba.getLastRow();


    if (
      ultimaLinha < 2
    ) {

      throw new Error(
        "Administrador inicial não encontrado."
      );

    }


    const dados =
      aba
        .getRange(
          2,
          1,
          ultimaLinha - 1,
          COL_USUARIO_UNIDADE_ID
        )
        .getValues();


    let linhaAdmin =
      0;


    for (
      let i = 0;
      i < dados.length;
      i++
    ) {

      if (
        String(
          dados[i][0]
        ) ===
        String(
          sessao.usuario.id
        )
      ) {

        linhaAdmin =
          i + 2;

        break;

      }

    }


    if (!linhaAdmin) {

      throw new Error(
        "Administrador não localizado."
      );

    }


    // Verifica duplicidade de e-mail.
    const emailNormalizado =
      novoEmail.toLowerCase();


    for (
      let i = 0;
      i < dados.length;
      i++
    ) {

      const id =
        String(
          dados[i][0]
        );


      const email =
        String(
          dados[i][
            COL_USUARIO_EMAIL - 1
          ] || ""
        )
          .trim()
          .toLowerCase();


      if (
        id !==
          String(
            sessao.usuario.id
          ) &&
        email &&
        email ===
          emailNormalizado
      ) {

        throw new Error(
          "Este e-mail já está em uso."
        );

      }

    }


    aba
      .getRange(
        linhaAdmin,
        4
      )
      .setValue(
        gerarHashSenha(
          novaSenha
        )
      );


    aba
      .getRange(
        linhaAdmin,
        COL_USUARIO_EMAIL
      )
      .setValue(
        novoEmail
      );


    aba
      .getRange(
        linhaAdmin,
        COL_USUARIO_SENHA_PROVISORIA
      )
      .setValue(
        "NÃO"
      );


    // Executa toda a preparação automática.
    instalarSistemaHoraAtividade();


    marcarSistemaInstalado_();


    SpreadsheetApp.flush();


    registrarLog(
      sessao.usuario.login,
      "PRIMEIRO_ACESSO_ADMIN",
      "Configuração inicial concluída."
    );


    return {

      sucesso:
        true,

      mensagem:
        "Configuração inicial concluída com sucesso."

    };


  } catch (erro) {

    return {

      sucesso:
        false,

      mensagem:
        erro.message

    };

  }

}


// ==========================================================
// PREPARAR CÓPIA LIMPA PARA DISTRIBUIÇÃO
//
// USAR APENAS NO ARQUIVO-MODELO/TESTE.
// Mantém UNIDADES, CONFIG e modelos ocultos.
// Limpa professores, usuários, logs e histórico.
// Cria um único ADMIN: admin / 123456.
// ==========================================================

function prepararCopiaLimpaParaDistribuicao() {

  const ss =
    getPlanilhaBase();


  garantirEstruturaMunicipal_();


  // Garante que o modelo oculto exista antes de limpar professores.
  garantirModeloInternoProfessor_();


  const abaUsuarios =
    ss.getSheetByName(
      ABA_USUARIOS
    );


  const abaProf =
    ss.getSheetByName(
      ABA_PROFESSORES
    );


  const abaLogs =
    ss.getSheetByName(
      ABA_LOGS
    );


  if (
    !abaUsuarios ||
    !abaProf ||
    !abaLogs
  ) {

    throw new Error(
      "Estrutura básica incompleta."
    );

  }


  // Mantém apenas cabeçalhos.
  if (
    abaUsuarios.getLastRow() > 1
  ) {

    abaUsuarios
      .getRange(
        2,
        1,
        abaUsuarios.getLastRow() - 1,
        Math.max(
          abaUsuarios.getLastColumn(),
          COL_USUARIO_UNIDADE_ID
        )
      )
      .clearContent();

  }


  if (
    abaProf.getLastRow() > 1
  ) {

    abaProf
      .getRange(
        2,
        1,
        abaProf.getLastRow() - 1,
        Math.max(
          abaProf.getLastColumn(),
          COL_PROFESSOR_UNIDADE_ID
        )
      )
      .clearContent();

  }


  if (
    abaLogs.getLastRow() > 1
  ) {

    abaLogs
      .getRange(
        2,
        1,
        abaLogs.getLastRow() - 1,
        abaLogs.getLastColumn()
      )
      .clearContent();

  }


  const historico =
    ss.getSheetByName(
      NOME_ABA_HISTORICO_PLANILHAS
    );


  if (
    historico &&
    historico.getLastRow() > 1
  ) {

    historico
      .getRange(
        2,
        1,
        historico.getLastRow() - 1,
        historico.getLastColumn()
      )
      .clearContent();

  }


  const novoId =
    1;


  abaUsuarios
    .appendRow(
      [
        novoId,
        "Administrador",
        LOGIN_ADMIN_INICIAL,
        gerarHashSenha(
          SENHA_ADMIN_INICIAL
        ),
        "ADMIN",
        "",
        "SIM",
        "",
        "SIM",
        ""
      ]
    );


  // Nova cópia/modelo deve exigir instalação no primeiro acesso.
  PropertiesService
    .getScriptProperties()
    .deleteProperty(
      CHAVE_SISTEMA_INSTALADO
    );


  PropertiesService
    .getScriptProperties()
    .deleteProperty(
      CHAVE_VERSAO_SISTEMA
    );


  // Mantém o vínculo com a planilha atual apenas para este arquivo.
  PropertiesService
    .getScriptProperties()
    .setProperty(
      CHAVE_ID_PLANILHA_BASE,
      ss.getId()
    );


  SpreadsheetApp.flush();


  ss.toast(
    "Cópia limpa preparada. Login inicial: admin / 123456",
    "Hora-Atividade",
    10
  );


  return {

    sucesso:
      true,

    login:
      LOGIN_ADMIN_INICIAL,

    senha:
      SENHA_ADMIN_INICIAL,

    mensagem:
      "Cópia limpa preparada para distribuição."

  };

}



