// ==========================================================

function getPlanilhaBase() {

  const propriedades =
    PropertiesService
      .getScriptProperties();


  const idInjetado =
    String(
      ID_PLANILHA_BASE_INSTALACAO || ""
    ).trim();


  if (
    idInjetado &&
    idInjetado !== "__PLANILHA_BASE_ID__"
  ) {

    propriedades.setProperty(
      CHAVE_ID_PLANILHA_BASE,
      idInjetado
    );

    return SpreadsheetApp.openById(
      idInjetado
    );

  }


  const idSalvo =
    String(
      propriedades.getProperty(
        CHAVE_ID_PLANILHA_BASE
      ) || ""
    ).trim();


  if (idSalvo) {

    try {

      return SpreadsheetApp.openById(
        idSalvo
      );

    } catch (erro) {

      // Continua para tentar recuperar a planilha vinculada.
    }

  }


  const ativa =
    SpreadsheetApp
      .getActiveSpreadsheet();


  if (ativa) {

    propriedades.setProperty(
      CHAVE_ID_PLANILHA_BASE,
      ativa.getId()
    );

    return ativa;

  }


  throw new Error(
    "Planilha-base não configurada. Abra a planilha do aplicativo e execute instalarSistemaHoraAtividade() uma vez."
  );

}


