// ==========================================================
// INSTALADOR / PORTABILIDADE
//
// EXECUTADO PELO MENU Hora-Atividade > Instalar sistema
// APÓS FAZER UMA CÓPIA DA PLANILHA PARA OUTRO DRIVE.
//
// Ele vincula o código à própria cópia atual, prepara a
// estrutura municipal, cria a pasta raiz, as pastas das
// unidades, garante o modelo interno e instala o gatilho anual.
// ==========================================================

function instalarSistemaHoraAtividade() {

  // Funciona tanto pelo editor da planilha quanto pelo Web App.
  // O instalador web injeta o ID da planilha-base no código.
  const atual =
    getPlanilhaBase();


  // Esta linha é essencial em uma nova cópia.
  // Mesmo que propriedades antigas tenham sido copiadas,
  // o ID passa a apontar para a planilha atual.
  PropertiesService
    .getScriptProperties()
    .setProperty(
      CHAVE_ID_PLANILHA_BASE,
      atual.getId()
    );


  const obrigatorias = [
    ABA_USUARIOS,
    ABA_PROFESSORES,
    ABA_CONFIG,
    ABA_LOGS
  ];


  obrigatorias.forEach(
    function(nome) {

      if (
        !atual.getSheetByName(
          nome
        )
      ) {

        throw new Error(
          "A cópia não possui a aba obrigatória " +
          nome +
          ". Use como modelo a planilha completa do aplicativo."
        );

      }

    }
  );


  garantirEstruturaMunicipal_();


  const modelo =
    garantirModeloInternoProfessor_();


  const pastas =
    criarPastasDasUnidades_();


  instalarAutomacaoViradaAnual();


  SpreadsheetApp.flush();


  marcarSistemaInstalado_();


  registrarLog(
    "SISTEMA",
    "INSTALACAO",
    "Instalação/portabilidade configurada na planilha " +
    atual.getId()
  );


  atual.toast(
    "Instalação concluída. O aplicativo está vinculado a esta cópia.",
    "Hora-Atividade",
    8
  );


  return {

    sucesso:
      true,

    planilhaBaseId:
      atual.getId(),

    pastaRaizId:
      obterPastaRaizHoraAtividade_()
        .getId(),

    unidadesPreparadas:
      pastas.criadasOuVerificadas,

    modeloInternoCriado:
      modelo.criado,

    mensagem:
      "Instalação concluída com sucesso."

  };

}


