// GARANTE COLUNAS DE E-MAIL / RECUPERAÇÃO
// ==========================================================

function garantirColunasRecuperacaoSenha_() {

  const ss =
    getPlanilhaBase();

  const aba =
    ss.getSheetByName(
      ABA_USUARIOS
    );

  if (!aba) {
    throw new Error(
      "A aba USUÁRIOS não foi encontrada."
    );
  }

  if (
    !String(
      aba
        .getRange(1, COL_USUARIO_EMAIL)
        .getValue() || ""
    ).trim()
  ) {

    aba
      .getRange(1, COL_USUARIO_EMAIL)
      .setValue("E-MAIL");

  }

  if (
    !String(
      aba
        .getRange(
          1,
          COL_USUARIO_SENHA_PROVISORIA
        )
        .getValue() || ""
    ).trim()
  ) {

    aba
      .getRange(
        1,
        COL_USUARIO_SENHA_PROVISORIA
      )
      .setValue("SENHA_PROVISORIA");

  }

}


// ==========================================================
// VALIDA E-MAIL
// ==========================================================

function emailValido_(
  email
) {

  email =
    String(
      email || ""
    )
      .trim()
      .toLowerCase();

  return (
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/
      .test(email)
  );

}


// ==========================================================
// VERIFICA E-MAIL DUPLICADO
// ==========================================================

function emailExiste_(
  email,
  ignorarUsuarioId
) {

  email =
    String(
      email || ""
    )
      .trim()
      .toLowerCase();

  if (!email) {
    return false;
  }

  garantirColunasRecuperacaoSenha_();

  const ss =
    getPlanilhaBase();

  const aba =
    ss.getSheetByName(
      ABA_USUARIOS
    );

  const ultimaLinha =
    aba.getLastRow();

  if (
    ultimaLinha < 2
  ) {
    return false;
  }

  const dados =
    aba
      .getRange(
        2,
        1,
        ultimaLinha - 1,
        9
      )
      .getValues();

  return dados.some(
    function(linha) {

      const usuarioId =
        linha[0];

      const emailLinha =
        String(
          linha[7] || ""
        )
          .trim()
          .toLowerCase();

      if (
        ignorarUsuarioId &&
        String(usuarioId) ===
        String(ignorarUsuarioId)
      ) {
        return false;
      }

      return (
        emailLinha === email
      );

    }
  );

}


// ==========================================================
// GERA SENHA PROVISÓRIA
// ==========================================================

function gerarSenhaProvisoria_() {

  const caracteres =
    "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";

  let senha = "";

  for (
    let i = 0;
    i < 8;
    i++
  ) {

    senha +=
      caracteres.charAt(
        Math.floor(
          Math.random() *
          caracteres.length
        )
      );

  }

  return senha;

}


// ==========================================================
// LOGIN
// ==========================================================

function fazerLogin(
  login,
  senha
) {

  try {

    login =
      String(login || "")
        .trim()
        .toLowerCase();


    senha =
      String(senha || "");


    if (
      !login ||
      !senha
    ) {

      return {

        sucesso: false,
        mensagem:
          "Informe usuário e senha."

      };

    }


    const ss =
      getPlanilhaBase();


    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    if (!aba) {

      return {

        sucesso: false,
        mensagem:
          "A aba USUÁRIOS não foi encontrada."

      };

    }


    const ultimaLinha =
      aba.getLastRow();


    if (ultimaLinha < 2) {

      return {

        sucesso: false,
        mensagem:
          "Nenhum usuário cadastrado."

      };

    }


    const dados =
      aba
        .getRange(
          2,
          1,
          ultimaLinha - 1,
          9
        )
        .getValues();


    const hashDigitado =
      gerarHashSenha(
        senha
      );


    for (
      let i = 0;
      i < dados.length;
      i++
    ) {

      const linha =
        dados[i];


      const id =
        linha[0];


      const nome =
        String(
          linha[1] || ""
        );


      const loginPlanilha =
        String(
          linha[2] || ""
        )
          .trim()
          .toLowerCase();


      const hashPlanilha =
        String(
          linha[3] || ""
        );


      const tipo =
        String(
          linha[4] || ""
        )
          .trim()
          .toUpperCase();


      const professorId =
        linha[5];


      const ativo =
        String(
          linha[6] || ""
        )
          .trim()
          .toUpperCase();


      const email =
        String(
          linha[7] || ""
        )
          .trim();


      const senhaProvisoria =
        String(
          linha[8] || ""
        )
          .trim()
          .toUpperCase();


      const unidadeId =
        linha[9];


      if (
        loginPlanilha === login &&
        hashPlanilha === hashDigitado &&
        ativo === "SIM"
      ) {

        const token =
          Utilities.getUuid();


        const sessao = {

          id: id,
          nome: nome,
          login: login,
          tipo: tipo,
          professorId:
            professorId,
          email: email,
          emailPendente:
            !emailValido_(email),
          senhaProvisoria:
            senhaProvisoria === "SIM",

          unidadeId:
            unidadeId

        };


        CacheService
          .getScriptCache()
          .put(

            "SESSAO_" + token,

            JSON.stringify(
              sessao
            ),

            21600

          );


        registrarLog(

          login,
          "LOGIN",
          "Login efetuado com sucesso"

        );


        return {

          sucesso: true,

          token: token,

          usuario: {

            id: id,
            nome: nome,
            login: login,
            tipo: tipo,
            professorId:
              professorId,
            email: email,
            emailPendente:
              !emailValido_(email),
            senhaProvisoria:
              senhaProvisoria === "SIM",

            unidadeId:
              unidadeId

          }

        };

      }

    }


    registrarLog(

      login,
      "LOGIN_NEGADO",
      "Usuário ou senha inválidos"

    );


    return {

      sucesso: false,
      mensagem:
        "Usuário ou senha inválidos."

    };


  } catch (erro) {

    Logger.log(
      "Erro no login: " +
      erro.message
    );


    return {

      sucesso: false,
      mensagem:
        "Erro ao efetuar login."

    };

  }

}


// ==========================================================
// ALTERA A PRÓPRIA SENHA
// ==========================================================

function alterarMinhaSenha(
  token,
  senhaAtual,
  novaSenha
) {

  try {

    const sessao =
      validarSessao(
        token
      );


    if (
      !sessao.valido ||
      sessao.usuario.tipo !==
        "PROFESSOR"
    ) {

      throw new Error(
        "Acesso não autorizado."
      );

    }


    senhaAtual =
      String(
        senhaAtual || ""
      );


    novaSenha =
      String(
        novaSenha || ""
      );


    if (
      !senhaAtual ||
      !novaSenha
    ) {

      throw new Error(
        "Informe a senha atual e a nova senha."
      );

    }


    if (
      novaSenha.length < 6
    ) {

      throw new Error(
        "A nova senha deve ter pelo menos 6 caracteres."
      );

    }


    if (
      senhaAtual ===
      novaSenha
    ) {

      throw new Error(
        "A nova senha deve ser diferente da senha atual."
      );

    }


    garantirColunasRecuperacaoSenha_();


    const ss =
      getPlanilhaBase();


    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    const ultimaLinha =
      aba.getLastRow();


    for (
      let linha = 2;
      linha <= ultimaLinha;
      linha++
    ) {

      const id =
        aba
          .getRange(
            linha,
            1
          )
          .getValue();


      if (
        String(id) !==
        String(
          sessao.usuario.id
        )
      ) {

        continue;

      }


      const hashAtual =
        String(
          aba
            .getRange(
              linha,
              4
            )
            .getValue() || ""
        );


      if (
        hashAtual !==
        gerarHashSenha(
          senhaAtual
        )
      ) {

        throw new Error(
          "A senha atual está incorreta."
        );

      }


      aba
        .getRange(
          linha,
          4
        )
        .setValue(
          gerarHashSenha(
            novaSenha
          )
        );


      aba
        .getRange(
          linha,
          COL_USUARIO_SENHA_PROVISORIA
        )
        .setValue(
          "NÃO"
        );


      registrarLog(

        sessao.usuario.login,

        "ALTERAR_PROPRIA_SENHA",

        "Professor alterou a própria senha"

      );


      return {

        sucesso: true,
        mensagem:
          "Senha alterada com sucesso."

      };

    }


    throw new Error(
      "Usuário não encontrado."
    );


  } catch (erro) {

    return {

      sucesso: false,
      mensagem:
        erro.message

    };

  }

}


// ==========================================================
// RECUPERAÇÃO DE SENHA POR E-MAIL
//
// Recebe login ou e-mail.
// Para não revelar se uma conta existe, o retorno ao navegador
// é sempre genérico quando não encontra o professor.
// ==========================================================

function solicitarRecuperacaoSenha(
  identificador
) {

  try {

    identificador =
      String(
        identificador || ""
      )
        .trim()
        .toLowerCase();


    if (!identificador) {

      return {

        sucesso: false,
        mensagem:
          "Informe seu usuário ou e-mail."

      };

    }


    garantirColunasRecuperacaoSenha_();


    const ss =
      getPlanilhaBase();


    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    const ultimaLinha =
      aba.getLastRow();


    if (
      ultimaLinha < 2
    ) {

      return {

        sucesso: true,
        mensagem:
          "Se os dados estiverem cadastrados, uma senha provisória será enviada para o e-mail do professor."

      };

    }


    const dados =
      aba
        .getRange(
          2,
          1,
          ultimaLinha - 1,
          9
        )
        .getValues();


    for (
      let i = 0;
      i < dados.length;
      i++
    ) {

      const linha =
        dados[i];


      const nome =
        String(
          linha[1] || ""
        ).trim();


      const login =
        String(
          linha[2] || ""
        )
          .trim()
          .toLowerCase();


      const tipo =
        String(
          linha[4] || ""
        )
          .trim()
          .toUpperCase();


      const ativo =
        String(
          linha[6] || ""
        )
          .trim()
          .toUpperCase();


      const email =
        String(
          linha[7] || ""
        )
          .trim()
          .toLowerCase();


      if (
        tipo !== "PROFESSOR" ||
        ativo !== "SIM" ||
        !email
      ) {

        continue;

      }


      if (
        identificador !== login &&
        identificador !== email
      ) {

        continue;

      }


      const linhaPlanilha =
        i + 2;


      const senhaAnterior =
        aba
          .getRange(
            linhaPlanilha,
            4
          )
          .getValue();


      const flagAnterior =
        aba
          .getRange(
            linhaPlanilha,
            COL_USUARIO_SENHA_PROVISORIA
          )
          .getValue();


      const senhaProvisoria =
        gerarSenhaProvisoria_();


      try {

        aba
          .getRange(
            linhaPlanilha,
            4
          )
          .setValue(
            gerarHashSenha(
              senhaProvisoria
            )
          );


        aba
          .getRange(
            linhaPlanilha,
            COL_USUARIO_SENHA_PROVISORIA
          )
          .setValue(
            "SIM"
          );


        SpreadsheetApp.flush();


        MailApp.sendEmail({

          to:
            email,

          subject:
            "Hora-Atividade - senha provisória",

          name:
            "Hora-Atividade",

          htmlBody:
            "<p>Olá, <strong>" +
            nome +
            "</strong>.</p>" +
            "<p>Foi solicitada a recuperação da sua senha no sistema Hora-Atividade.</p>" +
            "<p>Sua senha provisória é:</p>" +
            "<p style='font-size:22px;font-weight:bold;letter-spacing:2px;'>" +
            senhaProvisoria +
            "</p>" +
            "<p>Entre no sistema com essa senha e altere-a em <strong>Minha senha</strong>.</p>" +
            "<p>Se você não solicitou esta recuperação, informe a administração da escola.</p>"

        });


      } catch (erroEnvio) {

        // Restaura a senha anterior se o envio falhar.
        aba
          .getRange(
            linhaPlanilha,
            4
          )
          .setValue(
            senhaAnterior
          );


        aba
          .getRange(
            linhaPlanilha,
            COL_USUARIO_SENHA_PROVISORIA
          )
          .setValue(
            flagAnterior
          );


        SpreadsheetApp.flush();


        throw new Error(
          "Não foi possível enviar o e-mail de recuperação. Tente novamente mais tarde."
        );

      }


      registrarLog(

        login,

        "RECUPERAR_SENHA_EMAIL",

        "Senha provisória enviada para o e-mail cadastrado"

      );


      return {

        sucesso: true,
        mensagem:
          "Se os dados estiverem cadastrados, uma senha provisória será enviada para o e-mail do professor."

      };

    }


    return {

      sucesso: true,
      mensagem:
        "Se os dados estiverem cadastrados, uma senha provisória será enviada para o e-mail do professor."

    };


  } catch (erro) {

    Logger.log(
      "solicitarRecuperacaoSenha: " +
      erro.stack
    );


    return {

      sucesso: false,
      mensagem:
        erro.message

    };

  }

}


// ==========================================================
// VALIDA SESSÃO
// ==========================================================

function validarSessao(
  token,
  permitirEmailPendente
) {

  if (!token) {

    return {
      valido: false
    };

  }


  const cache =
    CacheService.getScriptCache();


  const sessaoTexto =
    cache.get(
      "SESSAO_" + token
    );


  if (!sessaoTexto) {

    return {
      valido: false
    };

  }


  const sessao =
    JSON.parse(
      sessaoTexto
    );


  if (
    sessao.emailPendente &&
    !permitirEmailPendente
  ) {

    return {

      valido: false,

      emailPendente:
        true,

      usuario:
        sessao

    };

  }


  return {

    valido: true,

    emailPendente:
      !!sessao.emailPendente,

    usuario:
      sessao

  };

}


// ==========================================================
// SALVA E-MAIL OBRIGATÓRIO DO USUÁRIO LOGADO
// ==========================================================

function salvarEmailObrigatorio(
  token,
  email
) {

  try {

    const sessao =
      validarSessao(
        token,
        true
      );


    if (
      !sessao.valido
    ) {

      throw new Error(
        "Sessão expirada. Faça login novamente."
      );

    }


    email =
      String(
        email || ""
      )
        .trim()
        .toLowerCase();


    if (
      !emailValido_(email)
    ) {

      throw new Error(
        "Informe um e-mail válido."
      );

    }


    if (
      emailExiste_(
        email,
        sessao.usuario.id
      )
    ) {

      throw new Error(
        "Este e-mail já está vinculado a outro usuário."
      );

    }


    garantirColunasRecuperacaoSenha_();


    const ss =
      getPlanilhaBase();


    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    const ultimaLinha =
      aba.getLastRow();


    for (
      let linha = 2;
      linha <= ultimaLinha;
      linha++
    ) {

      const id =
        aba
          .getRange(
            linha,
            1
          )
          .getValue();


      if (
        String(id) !==
        String(
          sessao.usuario.id
        )
      ) {

        continue;

      }


      aba
        .getRange(
          linha,
          COL_USUARIO_EMAIL
        )
        .setValue(
          email
        );


      sessao.usuario.email =
        email;

      sessao.usuario.emailPendente =
        false;


      CacheService
        .getScriptCache()
        .put(

          "SESSAO_" + token,

          JSON.stringify(
            sessao.usuario
          ),

          21600

        );


      registrarLog(

        sessao.usuario.login,

        "CADASTRAR_EMAIL",

        "Usuário cadastrou/atualizou o e-mail obrigatório"

      );


      return {

        sucesso: true,

        mensagem:
          "E-mail cadastrado com sucesso.",

        email:
          email

      };

    }


    throw new Error(
      "Usuário não encontrado."
    );


  } catch (erro) {

    return {

      sucesso: false,

      mensagem:
        erro.message

    };

  }

}


