// ==========================================================
// LISTA PROFESSORES - ADMIN
// ==========================================================

function listarProfessores(
  token,
  unidadeId
) {

  try {

    const sessao =
      validarSessao(
        token
      );

    const unidade =
      obterUnidadePermitida_(
        sessao,
        unidadeId
      );

    const ss =
      getPlanilhaBase();

    const aba =
      ss.getSheetByName(
        ABA_PROFESSORES
      );

    if (!aba) {
      throw new Error(
        "Aba PROFESSORES não encontrada."
      );
    }

    if (
      aba.getLastRow() < 2
    ) {
      return {
        sucesso: true,
        unidade: unidade,
        professores: []
      };
    }

    const dados =
      aba
        .getRange(
          2,
          1,
          aba.getLastRow() - 1,
          5
        )
        .getValues();

    const professores =
      dados
        .filter(
          function(linha) {
            return (
              String(linha[4]) ===
              String(unidade.id)
            );
          }
        )
        .map(
          function(linha) {
            return {
              id: linha[0],
              nome: linha[1],
              planilhaId: linha[2],
              ativo: linha[3],
              unidadeId: linha[4]
            };
          }
        )
        .sort(
          function(a, b) {
            return String(a.nome || "")
              .localeCompare(
                String(b.nome || ""),
                "pt-BR"
              );
          }
        );

    return {
      sucesso: true,
      unidade: unidade,
      professores: professores
    };

  } catch (erro) {

    return {
      sucesso: false,
      mensagem:
        erro.message
    };

  }

}


// ==========================================================
// CADASTRA PROFESSOR
// ==========================================================
//
// Mantém o parâmetro planilhaId por compatibilidade com o HTML
// atual, porém ele não é mais necessário. O sistema cria a
// planilha automaticamente.
//
function cadastrarProfessor(
  token,
  nome,
  planilhaId,
  login,
  senha,
  email,
  unidadeId
) {

  const sessao =
    validarSessao(
      token
    );


  let unidade;

  try {

    unidade =
      obterUnidadePermitida_(
        sessao,
        unidadeId
      );

  } catch (erro) {

    return {
      sucesso: false,
      mensagem:
        erro.message
    };

  }


  nome =
    String(nome || "")
      .trim();


  login =
    String(login || "")
      .trim()
      .toLowerCase();


  senha =
    String(senha || "");


  email =
    String(email || "")
      .trim()
      .toLowerCase();


  if (
    !nome ||
    !login ||
    !senha ||
    !email
  ) {

    return {

      sucesso: false,
      mensagem:
        "Informe nome, login, senha e e-mail."

    };

  }


  if (
    loginExiste(
      login
    )
  ) {

    return {

      sucesso: false,
      mensagem:
        "Este login já está cadastrado."

    };

  }


  if (
    !emailValido_(email)
  ) {

    return {

      sucesso: false,
      mensagem:
        "Informe um e-mail válido."

    };

  }


  if (
    emailExiste_(email)
  ) {

    return {

      sucesso: false,
      mensagem:
        "Este e-mail já está vinculado a outro usuário."

    };

  }


  garantirColunasRecuperacaoSenha_();


  // Garante que estamos trabalhando na pasta do ano atual
  // antes de entrar no bloqueio do cadastro.
  verificarViradaDeAno();


  const lock =
    LockService.getScriptLock();


  let arquivoCriado = null;


  try {

    lock.waitLock(
      30000
    );


    // Cria automaticamente a planilha do novo professor.
    const novaPlanilha =
      criarPlanilhaProfessorAutomaticamente_(
        nome,
        unidade.id
      );


    arquivoCriado =
      novaPlanilha.arquivo;


    planilhaId =
      novaPlanilha.planilhaId;


    const ss =
      getPlanilhaBase();


    const abaProf =
      ss.getSheetByName(
        ABA_PROFESSORES
      );


    const professorId =
      gerarProximoId(
        ABA_PROFESSORES
      );


    abaProf.appendRow([

      professorId,
      nome,
      planilhaId,
      "SIM",
      unidade.id

    ]);


    const abaUsuarios =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    const usuarioId =
      gerarProximoId(
        ABA_USUARIOS
      );


    abaUsuarios.appendRow([

      usuarioId,
      nome,
      login,
      gerarHashSenha(senha),
      "PROFESSOR",
      professorId,
      "SIM",
      email,
      "NÃO",
      unidade.id

    ]);


    registrarHistoricoPlanilha_(
      professorId,
      nome,
      obterAnoAtual_(),
      planilhaId,
      "CADASTRO"
    );


    registrarLog(

      sessao.usuario.login,

      "CADASTRAR_PROFESSOR",

      "Professor cadastrado: " +
      nome +
      " | unidade: " +
      unidade.nome +
      " | planilha criada automaticamente: " +
      planilhaId

    );


    return {

      sucesso: true,
      mensagem:
        "Professor cadastrado e planilha criada automaticamente.",
      professorId:
        professorId,
      planilhaId:
        planilhaId,
      planilhaUrl:
        novaPlanilha.url

    };


  } catch (erro) {

    Logger.log(
      "cadastrarProfessor: " +
      erro.stack
    );


    // Se a planilha foi criada mas o cadastro falhou antes
    // de terminar, ela é enviada à lixeira para não deixar
    // arquivo órfão.
    if (arquivoCriado) {

      try {
        arquivoCriado.setTrashed(true);
      } catch (e) {
      }

    }


    return {

      sucesso: false,
      mensagem:
        erro.message ||
        "Não foi possível cadastrar o professor."

    };


  } finally {

    try {
      lock.releaseLock();
    } catch (e) {
    }

  }

}


// ==========================================================
// DESATIVA PROFESSOR
// ==========================================================

function desativarProfessor(
  token,
  professorId
) {

  const sessao =
    validarSessao(
      token
    );


  if (
    !sessao.valido ||
    !["ADMIN", "DIRETOR"]
      .includes(
        sessao.usuario.tipo
      )
  ) {
    return {
      sucesso: false,
      mensagem:
        "Acesso não autorizado."
    };
  }

  const professorAcesso =
    buscarProfessorPorId(
      professorId
    );

  if (!professorAcesso) {
    return {
      sucesso: false,
      mensagem:
        "Professor não encontrado."
    };
  }

  if (
    sessao.usuario.tipo ===
      "DIRETOR" &&
    String(
      professorAcesso.unidadeId
    ) !==
    String(
      sessao.usuario.unidadeId
    )
  ) {
    return {
      sucesso: false,
      mensagem:
        "Acesso não autorizado a este professor."
    };
  }


  const ss =
    getPlanilhaBase();


  const abaProf =
    ss.getSheetByName(
      ABA_PROFESSORES
    );


  const ultimaLinha =
    abaProf.getLastRow();


  for (
    let linha = 2;
    linha <= ultimaLinha;
    linha++
  ) {

    const id =
      abaProf
        .getRange(
          linha,
          1
        )
        .getValue();


    if (
      String(id) ===
      String(professorId)
    ) {

      abaProf
        .getRange(
          linha,
          4
        )
        .setValue(
          "NÃO"
        );

      break;

    }

  }


  const abaUsuarios =
    ss.getSheetByName(
      ABA_USUARIOS
    );


  const ultimaLinhaUsuarios =
    abaUsuarios.getLastRow();


  for (
    let linha = 2;
    linha <=
      ultimaLinhaUsuarios;
    linha++
  ) {

    const professorUsuario =
      abaUsuarios
        .getRange(
          linha,
          6
        )
        .getValue();


    if (
      String(professorUsuario) ===
      String(professorId)
    ) {

      abaUsuarios
        .getRange(
          linha,
          7
        )
        .setValue(
          "NÃO"
        );

    }

  }


  registrarLog(

    sessao.usuario.login,

    "DESATIVAR_PROFESSOR",

    "Professor ID: " +
    professorId

  );


  return {

    sucesso: true,
    mensagem:
      "Professor desativado."

  };

}


// ==========================================================
// BUSCA PROFESSOR PELO ID
// ==========================================================

function buscarProfessorPorId(
  professorId
) {

  const ss =
    getPlanilhaBase();


  const aba =
    ss.getSheetByName(
      ABA_PROFESSORES
    );


  if (!aba) {
    return null;
  }


  const ultimaLinha =
    aba.getLastRow();


  if (ultimaLinha < 2) {
    return null;
  }


  const dados =
    aba
      .getRange(
        2,
        1,
        ultimaLinha - 1,
        5
      )
      .getValues();


  for (
    let i = 0;
    i < dados.length;
    i++
  ) {

    if (
      String(dados[i][0]) ===
      String(professorId)
    ) {

      return {

        id:
          dados[i][0],

        nome:
          dados[i][1],

        planilhaId:
          dados[i][2],

        ativo:
          dados[i][3],

        unidadeId:
          dados[i][4]

      };

    }

  }


  return null;

}


// ==========================================================
// DADOS DO PROFESSOR LOGADO
// ==========================================================

function obterDadosProfessor(
  token
) {

  const sessao =
    validarSessao(
      token
    );


  if (
    !sessao.valido ||
    sessao.usuario.tipo !==
      "PROFESSOR"
  ) {

    return {

      sucesso: false,
      mensagem:
        "Acesso não autorizado."

    };

  }


  const professor =
    buscarProfessorPorId(
      sessao.usuario.professorId
    );


  if (!professor) {

    return {

      sucesso: false,
      mensagem:
        "Professor não encontrado."

    };

  }


  return {

    sucesso: true,
    professor:
      professor

  };

}


// ==========================================================
// OBTÉM PLANILHA DO PROFESSOR LOGADO
//
// SEGURANÇA:
// O ID DA PLANILHA NÃO VEM DO NAVEGADOR.
// ELE É OBTIDO PELO PROFESSOR_ID DA SESSÃO.
// ==========================================================

function obterPlanilhaDoProfessorLogado(
  token
) {

  const sessao =
    validarSessao(
      token
    );


  if (
    !sessao.valido ||
    sessao.usuario.tipo !==
      "PROFESSOR"
  ) {

    throw new Error(
      "Acesso não autorizado."
    );

  }


  const professor =
    buscarProfessorPorId(
      sessao.usuario.professorId
    );


  if (!professor) {

    throw new Error(
      "Professor não encontrado."
    );

  }


  if (
    String(
      professor.ativo || ""
    )
      .trim()
      .toUpperCase()
    !==
    "SIM"
  ) {

    throw new Error(
      "Professor está desativado."
    );

  }


  if (!professor.planilhaId) {

    throw new Error(
      "Professor sem planilha vinculada."
    );

  }


  let ssProfessor;


  try {

    ssProfessor =
      SpreadsheetApp.openById(
        professor.planilhaId
      );

  } catch (erro) {

    throw new Error(
      "Não foi possível acessar sua planilha de Hora-Atividade."
    );

  }


  return {

    sessao:
      sessao,

    professor:
      professor,

    planilha:
      ssProfessor

  };

}


// ==========================================================
// LISTA OS MESES DO PROFESSOR
// ==========================================================

function listarMesesProfessor(
  token
) {

  try {

    const dados =
      obterPlanilhaDoProfessorLogado(
        token
      );


    const resultado = [];


    MESES_HORA_ATIVIDADE
      .forEach(
        function(mes) {

          const aba =
            localizarAbaMes(
              dados.planilha,
              mes
            );


          if (!aba) {

            resultado.push({

              mes:
                mes,

              existe:
                false,

              totalMinutos:
                0,

              registros:
                0

            });

            return;

          }


          const total =
            lerNumeroSeguro(
              aba
                .getRange("B57")
                .getValue()
            );


          const quantidadeLinhas =
            LINHA_FINAL_REGISTROS -
            LINHA_INICIAL_REGISTROS +
            1;


          // Lê A até I de uma vez
          const registros =
            aba
              .getRange(
                LINHA_INICIAL_REGISTROS,
                1,
                quantidadeLinhas,
                9
              )
              .getValues();


          let quantidade =
            0;


          registros.forEach(
            function(linha) {

              const data =
                linha[0];

              const minutos =
                linha[1];

              const atividade =
                linha[3];

              const observacao =
                linha[8];


              if (
                data ||
                minutos ||
                atividade ||
                observacao
              ) {

                quantidade++;

              }

            }
          );


          resultado.push({

            mes:
              mes,

            existe:
              true,

            totalMinutos:
              total,

            registros:
              quantidade

          });

        }
      );


    return {

      sucesso: true,

      professor: {

        id:
          dados.professor.id,

        nome:
          dados.professor.nome

      },

      meses:
        resultado

    };


  } catch (erro) {

    Logger.log(
      "listarMesesProfessor: " +
      erro.stack
    );


    return {

      sucesso: false,
      mensagem:
        erro.message

    };

  }

}


// ==========================================================
// ABRE UM MÊS DO PROFESSOR
// ==========================================================

function obterMesProfessor(
  token,
  mes
) {

  try {

    const dados =
      obterPlanilhaDoProfessorLogado(
        token
      );


    mes =
      normalizarMesHoraAtividade(
        mes
      );


    if (
      !MESES_HORA_ATIVIDADE
        .includes(mes)
    ) {

      throw new Error(
        "Mês inválido."
      );

    }


    const aba =
      localizarAbaMes(
        dados.planilha,
        mes
      );


    if (!aba) {

      throw new Error(
        "Aba de " +
        mes +
        " não encontrada."
      );

    }


    // ------------------------------------------------------
    // ATIVIDADES ACEITAS PELA LISTA SUSPENSA
    // ------------------------------------------------------

    const atividades =
      lerAtividadesDisponiveis(
        aba
      );


    const quantidade =
      LINHA_FINAL_REGISTROS -
      LINHA_INICIAL_REGISTROS +
      1;


    const valores =
      aba
        .getRange(
          LINHA_INICIAL_REGISTROS,
          1,
          quantidade,
          9
        )
        .getValues();


    const exibidos =
      aba
        .getRange(
          LINHA_INICIAL_REGISTROS,
          1,
          quantidade,
          9
        )
        .getDisplayValues();


    const registros = [];


    for (
      let i = 0;
      i < quantidade;
      i++
    ) {

      const linhaPlanilha =
        LINHA_INICIAL_REGISTROS +
        i;


      const valorData =
        valores[i][0];


      const minutos =
        lerNumeroSeguro(
          valores[i][1]
        );


      // D é a primeira célula
      // da área D:H
      const atividade =
        String(
          exibidos[i][3] || ""
        ).trim();


      const observacao =
        String(
          exibidos[i][8] || ""
        ).trim();


      if (
        !valorData &&
        !minutos &&
        !atividade &&
        !observacao
      ) {

        continue;

      }


      registros.push({

        linha:
          linhaPlanilha,

        data:
          formatarDataParaTela(
            valorData,
            aba
          ),

        dataInput:
          formatarDataParaInput(
            valorData,
            aba
          ),

        minutos:
          minutos,

        atividade:
          atividade,

        observacao:
          observacao

      });

    }


    const totalMinutos =
      lerNumeroSeguro(
        aba
          .getRange("B57")
          .getValue()
      );


    return {

      sucesso: true,

      mes:
        mes,

      totalMinutos:
        totalMinutos,

      atividades:
        atividades,

      registros:
        registros

    };


  } catch (erro) {

    Logger.log(
      "obterMesProfessor: " +
      erro.stack
    );


    return {

      sucesso: false,
      mensagem:
        erro.message

    };

  }

}


// ==========================================================
// VISUALIZA A PLANILHA DO MÊS EM PDF
// ==========================================================
//
// Gera uma pré-visualização da aba real do mês selecionado.
// O PDF é devolvido ao navegador em Base64 e não é salvo
// permanentemente no Drive.
//
function gerarVisualizacaoPlanilhaMes(
  token,
  mes,
  professorId
) {

  let planilhaTemporaria = null;

  try {

    let dados = null;


    if (professorId) {

      const sessao =
        validarSessao(
          token
        );


      if (
        !sessao.valido ||
        !["ADMIN", "DIRETOR"]
          .includes(
            sessao.usuario.tipo
          )
      ) {

        throw new Error(
          "Acesso não autorizado."
        );

      }


      const professor =
        buscarProfessorPorId(
          professorId
        );


      if (!professor) {

        throw new Error(
          "Professor não encontrado."
        );

      }


      if (
        sessao.usuario.tipo ===
          "DIRETOR" &&
        String(
          professor.unidadeId
        ) !==
        String(
          sessao.usuario.unidadeId
        )
      ) {

        throw new Error(
          "Acesso não autorizado a este professor."
        );

      }


      dados = {

        professor:
          professor,

        planilha:
          SpreadsheetApp.openById(
            professor.planilhaId
          )

      };


    } else {

      dados =
        obterPlanilhaDoProfessorLogado(
          token
        );

    }


    mes =
      normalizarMesHoraAtividade(
        mes
      );


    if (
      !MESES_HORA_ATIVIDADE
        .includes(mes)
    ) {

      throw new Error(
        "Mês inválido."
      );

    }


    const abaOriginal =
      localizarAbaMes(
        dados.planilha,
        mes
      );


    if (!abaOriginal) {

      throw new Error(
        "Aba de " +
        mes +
        " não encontrada."
      );

    }


    // ------------------------------------------------------
    // GARANTE O NOME NA PLANILHA REAL
    // ------------------------------------------------------
    //
    // Se B10 fizer parte de uma célula mesclada, grava na
    // primeira célula da mesclagem, que é a célula exibida.
    //
    const celulaNomeOriginal =
      abaOriginal.getRange("B10");

    const mesclagensNome =
      celulaNomeOriginal.getMergedRanges();

    const destinoNomeOriginal =
      mesclagensNome.length
        ? mesclagensNome[0].getCell(1, 1)
        : celulaNomeOriginal;

    destinoNomeOriginal
      .clearDataValidations();

    destinoNomeOriginal
      .setValue(
        dados.professor.nome
      );


    SpreadsheetApp.flush();


    // ------------------------------------------------------
    // CRIA UMA CÓPIA TEMPORÁRIA SOMENTE PARA IMPRESSÃO
    // ------------------------------------------------------
    //
    // Isso evita que linhas/colunas extras ou configurações
    // antigas de impressão façam o PDF sair em mais páginas.
    //
    planilhaTemporaria =
      SpreadsheetApp.create(
        "Visualização temporária - " +
        dados.professor.nome +
        " - " +
        mes
      );


    const abaTemporaria =
      abaOriginal.copyTo(
        planilhaTemporaria
      );


    // Remove a aba vazia criada automaticamente.
    const abasTemp =
      planilhaTemporaria.getSheets();

    abasTemp.forEach(
      function(aba) {

        if (
          aba.getSheetId() !==
          abaTemporaria.getSheetId()
        ) {

          planilhaTemporaria
            .deleteSheet(
              aba
            );

        }

      }
    );


    abaTemporaria
      .setName(
        mes
      );


    // Garante novamente o nome na cópia temporária.
    const celulaNomeTemp =
      abaTemporaria.getRange("B10");

    const mesclagensNomeTemp =
      celulaNomeTemp.getMergedRanges();

    const destinoNomeTemp =
      mesclagensNomeTemp.length
        ? mesclagensNomeTemp[0].getCell(1, 1)
        : celulaNomeTemp;

    destinoNomeTemp
      .clearDataValidations();

    destinoNomeTemp
      .setValue(
        dados.professor.nome
      );


    // Mantém APENAS A1:I57 na planilha temporária.
    const maxLinhas =
      abaTemporaria.getMaxRows();

    if (
      maxLinhas > 57
    ) {

      abaTemporaria.deleteRows(
        58,
        maxLinhas - 57
      );

    }


    const maxColunas =
      abaTemporaria.getMaxColumns();

    if (
      maxColunas > 9
    ) {

      abaTemporaria.deleteColumns(
        10,
        maxColunas - 9
      );

    }


    SpreadsheetApp.flush();


    // ------------------------------------------------------
    // EXPORTA A CÓPIA TEMPORÁRIA EM UMA ÚNICA PÁGINA A4
    // ------------------------------------------------------
    //
    // scale=4 = ajustar toda a folha em uma página.
    //
    const spreadsheetId =
      planilhaTemporaria.getId();


    const gid =
      abaTemporaria.getSheetId();


    const url =
      "https://docs.google.com/spreadsheets/d/" +
      spreadsheetId +
      "/export" +
      "?format=pdf" +
      "&gid=" +
      gid +
      "&size=A4" +
      "&portrait=true" +
      "&scale=4" +
      "&sheetnames=false" +
      "&printtitle=false" +
      "&pagenumbers=false" +
      "&gridlines=false" +
      "&fzr=false" +
      "&attachment=false" +
      "&horizontal_alignment=CENTER" +
      "&vertical_alignment=TOP" +
      "&top_margin=0.10" +
      "&bottom_margin=0.10" +
      "&left_margin=0.10" +
      "&right_margin=0.10";


    const resposta =
      UrlFetchApp.fetch(
        url,
        {
          headers: {
            Authorization:
              "Bearer " +
              ScriptApp.getOAuthToken()
          },
          muteHttpExceptions:
            true
        }
      );


    const codigo =
      resposta.getResponseCode();


    if (
      codigo !== 200
    ) {

      Logger.log(
        "Falha ao exportar PDF. HTTP " +
        codigo +
        " | " +
        resposta.getContentText()
      );

      throw new Error(
        "Não foi possível gerar a visualização da planilha."
      );

    }


    const blob =
      resposta.getBlob()
        .setName(
          dados.professor.nome +
          " - " +
          mes +
          ".pdf"
        );


    return {

      sucesso:
        true,

      mes:
        mes,

      nomeArquivo:
        blob.getName(),

      mimeType:
        "application/pdf",

      base64:
        Utilities.base64Encode(
          blob.getBytes()
        )

    };


  } catch (erro) {

    Logger.log(
      "gerarVisualizacaoPlanilhaMes: " +
      erro.stack
    );


    return {

      sucesso:
        false,

      mensagem:
        erro.message

    };


  } finally {

    // A cópia existe somente durante a geração do PDF.
    // Depois é enviada à lixeira para não acumular arquivos.
    if (
      planilhaTemporaria
    ) {

      try {

        DriveApp
          .getFileById(
            planilhaTemporaria.getId()
          )
          .setTrashed(
            true
          );

      } catch (erroLimpeza) {

        Logger.log(
          "Não foi possível excluir a planilha temporária: " +
          erroLimpeza.message
        );

      }

    }

  }

}


// ==========================================================
// LÊ AS OPÇÕES EXATAS DO MENU SUSPENSO
//
// ESTA É A CORREÇÃO PRINCIPAL.
//
// Exemplo do valor real:
// "9) Aperfeiçoamento profissional - descrever o curso e o local"
//
// NÃO gravamos apenas "9".
// ==========================================================

function lerAtividadesDisponiveis(
  aba
) {

  const atividades = [];


  // Testa as células de registro até encontrar
  // uma que tenha validação de dados.
  let validacao = null;


  for (
    let linha =
      LINHA_INICIAL_REGISTROS;
    linha <=
      LINHA_FINAL_REGISTROS;
    linha++
  ) {

    validacao =
      aba
        .getRange(
          linha,
          4
        )
        .getDataValidation();


    if (validacao) {
      break;
    }

  }


  // --------------------------------------------------------
  // TENTA LER A VALIDAÇÃO ORIGINAL
  // --------------------------------------------------------

  if (validacao) {

    const tipo =
      validacao
        .getCriteriaType();


    const argumentos =
      validacao
        .getCriteriaValues();


    // ======================================================
    // LISTA DIGITADA DIRETAMENTE
    // ======================================================

    if (
      tipo ===
      SpreadsheetApp
        .DataValidationCriteria
        .VALUE_IN_LIST
    ) {

      const opcoes =
        argumentos[0] || [];


      opcoes.forEach(
        function(opcao) {

          const valor =
            String(
              opcao || ""
            ).trim();


          if (!valor) {
            return;
          }


          atividades.push({

            valor:
              valor,

            descricao:
              valor

          });

        }
      );


      return atividades;

    }


    // ======================================================
    // LISTA VINDO DE INTERVALO
    // ======================================================

    if (
      tipo ===
      SpreadsheetApp
        .DataValidationCriteria
        .VALUE_IN_RANGE
    ) {

      const intervalo =
        argumentos[0];


      if (intervalo) {

        const opcoes =
          intervalo
            .getDisplayValues()
            .flat();


        opcoes.forEach(
          function(opcao) {

            const valor =
              String(
                opcao || ""
              ).trim();


            if (!valor) {
              return;
            }


            atividades.push({

              valor:
                valor,

              descricao:
                valor

            });

          }
        );

      }


      if (
        atividades.length > 0
      ) {

        return atividades;

      }

    }

  }


  // ========================================================
  // PLANO B
  //
  // CASO NÃO SEJA POSSÍVEL LER A VALIDAÇÃO,
  // USA A TABELA DAS LINHAS 19 A 27.
  // ========================================================

  const dadosTabela =
    aba
      .getRange(
        19,
        1,
        9,
        2
      )
      .getDisplayValues();


  dadosTabela.forEach(
    function(linha) {

      const codigo =
        String(
          linha[0] || ""
        ).trim();


      const descricao =
        String(
          linha[1] || ""
        ).trim();


      if (
        !codigo ||
        !descricao
      ) {

        return;

      }


      // Formato mostrado pela validação:
      // 1) Descrição...
      const valor =
        codigo +
        ") " +
        descricao;


      atividades.push({

        valor:
          valor,

        descricao:
          valor

      });

    }
  );


  return atividades;

}


// ==========================================================
// SALVA NOVO REGISTRO OU ALTERA EXISTENTE
// ==========================================================

function salvarRegistroProfessor(
  token,
  mes,
  registro
) {

  const lock =
    LockService.getScriptLock();


  try {

    lock.waitLock(
      15000
    );


    const dados =
      obterPlanilhaDoProfessorLogado(
        token
      );


    mes =
      normalizarMesHoraAtividade(
        mes
      );


    if (
      !MESES_HORA_ATIVIDADE
        .includes(mes)
    ) {

      throw new Error(
        "Mês inválido."
      );

    }


    const aba =
      localizarAbaMes(
        dados.planilha,
        mes
      );


    if (!aba) {

      throw new Error(
        "Aba do mês não encontrada."
      );

    }


    if (!registro) {

      throw new Error(
        "Registro inválido."
      );

    }


    const dataTexto =
      String(
        registro.data || ""
      ).trim();


    const minutos =
      Number(
        registro.minutos
      );


    // Aqui recebemos o TEXTO EXATO
    // da lista suspensa.
    const atividade =
      String(
        registro.atividade || ""
      ).trim();


    const observacao =
      String(
        registro.observacao || ""
      ).trim();


    if (!dataTexto) {

      throw new Error(
        "Informe a data."
      );

    }


    if (
      !Number.isFinite(minutos) ||
      minutos <= 0
    ) {

      throw new Error(
        "Informe uma quantidade válida de minutos."
      );

    }


    if (!atividade) {

      throw new Error(
        "Selecione a atividade."
      );

    }


    // ------------------------------------------------------
    // CONFIRMA QUE O VALOR EXISTE NA LISTA REAL
    // ------------------------------------------------------

    const atividades =
      lerAtividadesDisponiveis(
        aba
      );


    const atividadeEncontrada =
      atividades.find(
        function(item) {

          return (
            String(
              item.valor
            ).trim()
            ===
            String(
              atividade
            ).trim()
          );

        }
      );


    if (!atividadeEncontrada) {

      throw new Error(
        "A atividade selecionada não é válida."
      );

    }


    // ------------------------------------------------------
    // DEFINE SE É NOVO OU EDIÇÃO
    // ------------------------------------------------------

    let linha =
      Number(
        registro.linha
      );


    let editando =
      false;


    if (
      linha >=
        LINHA_INICIAL_REGISTROS &&
      linha <=
        LINHA_FINAL_REGISTROS
    ) {

      editando =
        true;

    } else {

      linha =
        encontrarPrimeiraLinhaLivre(
          aba
        );

    }


    if (!linha) {

      throw new Error(
        "Não existem mais linhas disponíveis neste mês."
      );

    }


    const data =
      converterDataInput(
        dataTexto
      );


    if (!data) {

      throw new Error(
        "Data inválida."
      );

    }


    // ======================================================
    // PRIMEIRO GRAVAMOS A ATIVIDADE
    //
    // Dessa forma, caso a validação recusasse algum valor,
    // data/minutos não seriam escritos antes do erro.
    // ======================================================

    const celulaAtividade =
      aba.getRange(
        linha,
        4
      );


    celulaAtividade
      .setValue(
        atividadeEncontrada.valor
      );


    // ------------------------------------------------------
    // DATA
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        1
      )
      .setValue(
        data
      )
      .setNumberFormat(
        "dd/MM/yyyy"
      );


    // ------------------------------------------------------
    // MINUTOS
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        2
      )
      .setValue(
        Math.round(
          minutos
        )
      );


    // ------------------------------------------------------
    // OBSERVAÇÃO
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        9
      )
      .setValue(
        observacao
      );


    // COLUNA C NÃO É ALTERADA.
    // NELA JÁ EXISTE O TEXTO "min".


    SpreadsheetApp.flush();


    registrarLog(

      dados.sessao.usuario.login,

      editando
        ?
        "EDITAR_HORA_ATIVIDADE"
        :
        "ADICIONAR_HORA_ATIVIDADE",

      dados.professor.nome +
      " | " +
      mes +
      " | linha " +
      linha +
      " | " +
      Math.round(minutos) +
      " min | " +
      atividadeEncontrada.valor

    );


    return {

      sucesso: true,

      mensagem:
        editando
          ?
          "Registro atualizado com sucesso."
          :
          "Registro adicionado com sucesso."

    };


  } catch (erro) {

    Logger.log(
      "salvarRegistroProfessor: " +
      erro.stack
    );


    return {

      sucesso: false,
      mensagem:
        erro.message

    };


  } finally {

    try {

      lock.releaseLock();

    } catch (e) {

    }

  }

}


// ==========================================================
// EXCLUI REGISTRO
// ==========================================================

function excluirRegistroProfessor(
  token,
  mes,
  linha
) {

  const lock =
    LockService.getScriptLock();


  try {

    lock.waitLock(
      15000
    );


    const dados =
      obterPlanilhaDoProfessorLogado(
        token
      );


    mes =
      normalizarMesHoraAtividade(
        mes
      );


    linha =
      Number(
        linha
      );


    if (
      !MESES_HORA_ATIVIDADE
        .includes(mes)
    ) {

      throw new Error(
        "Mês inválido."
      );

    }


    if (
      linha <
        LINHA_INICIAL_REGISTROS ||
      linha >
        LINHA_FINAL_REGISTROS
    ) {

      throw new Error(
        "Linha inválida."
      );

    }


    const aba =
      localizarAbaMes(
        dados.planilha,
        mes
      );


    if (!aba) {

      throw new Error(
        "Aba não encontrada."
      );

    }


    // ------------------------------------------------------
    // A - DATA
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        1
      )
      .clearContent();


    // ------------------------------------------------------
    // B - MINUTOS
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        2
      )
      .clearContent();


    // ------------------------------------------------------
    // D:H - ATIVIDADE
    //
    // Preserva formatação e validação.
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        4,
        1,
        5
      )
      .clearContent();


    // ------------------------------------------------------
    // I - OBSERVAÇÃO
    // ------------------------------------------------------

    aba
      .getRange(
        linha,
        9
      )
      .clearContent();


    // C NÃO É ALTERADA


    SpreadsheetApp.flush();


    registrarLog(

      dados.sessao.usuario.login,

      "EXCLUIR_HORA_ATIVIDADE",

      dados.professor.nome +
      " | " +
      mes +
      " | linha " +
      linha

    );


    return {

      sucesso: true,
      mensagem:
        "Registro excluído."

    };


  } catch (erro) {

    Logger.log(
      "excluirRegistroProfessor: " +
      erro.stack
    );


    return {

      sucesso: false,
      mensagem:
        erro.message

    };


  } finally {

    try {

      lock.releaseLock();

    } catch (e) {

    }

  }

}


// ==========================================================
// PRIMEIRA LINHA VAZIA ENTRE 32 E 56
// ==========================================================

function encontrarPrimeiraLinhaLivre(
  aba
) {

  const quantidade =
    LINHA_FINAL_REGISTROS -
    LINHA_INICIAL_REGISTROS +
    1;


  const dados =
    aba
      .getRange(
        LINHA_INICIAL_REGISTROS,
        1,
        quantidade,
        9
      )
      .getValues();


  for (
    let i = 0;
    i < dados.length;
    i++
  ) {

    const linha =
      dados[i];


    const data =
      linha[0];

    const minutos =
      linha[1];

    const atividade =
      linha[3];

    const observacao =
      linha[8];


    if (
      !data &&
      !minutos &&
      !atividade &&
      !observacao
    ) {

      return (
        LINHA_INICIAL_REGISTROS +
        i
      );

    }

  }


  return null;

}


// ==========================================================
// LOCALIZA ABA DO MÊS
// ==========================================================

function localizarAbaMes(
  planilha,
  mes
) {

  const procurado =
    normalizarMesHoraAtividade(
      mes
    );


  const abas =
    planilha.getSheets();


  for (
    let i = 0;
    i < abas.length;
    i++
  ) {

    const nome =
      normalizarMesHoraAtividade(
        abas[i].getName()
      );


    if (
      nome ===
      procurado
    ) {

      return abas[i];

    }

  }


  return null;

}


// ==========================================================
// NORMALIZA NOME DO MÊS
// ==========================================================

function normalizarMesHoraAtividade(
  texto
) {

  if (!texto) {

    return "";

  }


  const valor =
    String(texto)
      .trim()
      .toUpperCase()
      .normalize("NFD")
      .replace(
        /[\u0300-\u036f]/g,
        ""
      );


  const meses = {

    "JANEIRO":
      "JANEIRO",

    "FEVEREIRO":
      "FEVEREIRO",

    "MARCO":
      "MARÇO",

    "ABRIL":
      "ABRIL",

    "MAIO":
      "MAIO",

    "JUNHO":
      "JUNHO",

    "JULHO":
      "JULHO",

    "AGOSTO":
      "AGOSTO",

    "SETEMBRO":
      "SETEMBRO",

    "OUTUBRO":
      "OUTUBRO",

    "NOVEMBRO":
      "NOVEMBRO",

    "DEZEMBRO":
      "DEZEMBRO"

  };


  for (
    const chave in meses
  ) {

    if (
      valor.indexOf(
        chave
      ) >= 0
    ) {

      return meses[chave];

    }

  }


  return valor;

}


// ==========================================================
// CONVERTE VALOR EM NÚMERO
// ==========================================================

function lerNumeroSeguro(
  valor
) {

  if (
    typeof valor === "number" &&
    !isNaN(valor)
  ) {

    return Math.round(
      valor
    );

  }


  const convertido =
    Number(
      String(
        valor || ""
      )
        .trim()
        .replace(
          ",",
          "."
        )
    );


  if (
    isNaN(
      convertido
    )
  ) {

    return 0;

  }


  return Math.round(
    convertido
  );

}


// ==========================================================
// DATA PARA EXIBIÇÃO
// ==========================================================

function formatarDataParaTela(
  valor,
  aba
) {

  if (!valor) {

    return "";

  }


  if (
    Object.prototype
      .toString
      .call(valor)
    ===
    "[object Date]"
    &&
    !isNaN(
      valor.getTime()
    )
  ) {

    return Utilities
      .formatDate(

        valor,

        aba
          .getParent()
          .getSpreadsheetTimeZone(),

        "dd/MM/yyyy"

      );

  }


  return String(
    valor
  );

}


// ==========================================================
// DATA PARA INPUT HTML
// ==========================================================

function formatarDataParaInput(
  valor,
  aba
) {

  if (!valor) {

    return "";

  }


  if (
    Object.prototype
      .toString
      .call(valor)
    ===
    "[object Date]"
    &&
    !isNaN(
      valor.getTime()
    )
  ) {

    return Utilities
