      );

  }


  return "";

}


// ==========================================================
// CONVERTE YYYY-MM-DD PARA DATE
// ==========================================================

function converterDataInput(
  texto
) {

  const partes =
    String(
      texto || ""
    )
      .split("-");


  if (
    partes.length !== 3
  ) {

    return null;

  }


  const ano =
    Number(
      partes[0]
    );


  const mes =
    Number(
      partes[1]
    );


  const dia =
    Number(
      partes[2]
    );


  if (
    !ano ||
    !mes ||
    !dia
  ) {

    return null;

  }


  // Meio-dia evita problemas
  // de mudança de data por timezone.
  const data =
    new Date(
      ano,
      mes - 1,
      dia,
      12,
      0,
      0
    );


  if (
    data.getFullYear() !==
      ano ||
    data.getMonth() !==
      mes - 1 ||
    data.getDate() !==
      dia
  ) {

    return null;

  }


  return data;

}


// ==========================================================
// VERIFICA LOGIN DUPLICADO
// ==========================================================

function loginExiste(
  login
) {

  const ss =
    getPlanilhaBase();


  const aba =
    ss.getSheetByName(
      ABA_USUARIOS
    );


  const ultimaLinha =
    aba.getLastRow();


  if (
    ultimaLinha < 2
  ) {

    return false;

  }


  const logins =
    aba
      .getRange(
        2,
        3,
        ultimaLinha - 1,
        1
      )
      .getValues()
      .flat();


  return logins.some(
    function(item) {

      return (
        String(item || "")
          .trim()
          .toLowerCase()
        ===
        login
      );

    }
  );

}


// ==========================================================
// PRÓXIMO ID
// ==========================================================

function gerarProximoId(
  nomeAba
) {

  const ss =
    getPlanilhaBase();


  const aba =
    ss.getSheetByName(
      nomeAba
    );


  const ultimaLinha =
    aba.getLastRow();


  if (
    ultimaLinha < 2
  ) {

    return 1;

  }


  const ids =
    aba
      .getRange(
        2,
        1,
        ultimaLinha - 1,
        1
      )
      .getValues()
      .flat()
      .map(
        function(valor) {

          return (
            Number(valor) || 0
          );

        }
      );


  const maior =
    Math.max.apply(
      null,
      ids
    );


  return maior + 1;

}


// ==========================================================
// HASH SHA-256 DA SENHA
// ==========================================================

function gerarHashSenha(
  senha
) {

  const bytes =
    Utilities.computeDigest(

      Utilities
        .DigestAlgorithm
        .SHA_256,

      String(senha),

      Utilities
        .Charset
        .UTF_8

    );


  return bytes
    .map(
      function(byte) {

        const valor =
          byte < 0
            ?
            byte + 256
            :
            byte;


        return (
          "0" +
          valor.toString(16)
        ).slice(-2);

      }
    )
    .join("");

}


// ==========================================================
// EXTRAI ID DA PLANILHA
// ==========================================================

function extrairIdPlanilha(
  valor
) {

  valor =
    String(
      valor || ""
    )
      .trim();


  if (!valor) {

    return "";

  }


  const match =
    valor.match(
      /\/d\/([a-zA-Z0-9-_]+)/
    );


  if (
    match &&
    match[1]
  ) {

    return match[1];

  }


  return valor;

}


