// ==========================================================
// PASTAS DO SISTEMA
// ==========================================================
//
// A pasta raiz "Hora Atividade" é procurada no mesmo contexto
// de Drive da planilha-base. Dentro dela ficam as pastas anuais:
// "Hora Atividade - 2026", "Hora Atividade - 2027", etc.
//

function obterPastaRaizHoraAtividade_() {

  const arquivoBase =
    DriveApp.getFileById(
      getPlanilhaBase().getId()
    );


  const pais =
    arquivoBase.getParents();


  // Primeiro procura entre as pastas irmãs da planilha-base.
  if (pais.hasNext()) {

    const pastaOndeEstaPrograma =
      pais.next();


    // Se a própria pasta já for "Hora Atividade", usa ela.
    if (
      String(
        pastaOndeEstaPrograma.getName() || ""
      ).trim() ===
      NOME_PASTA_RAIZ_HORA_ATIVIDADE
    ) {

      return pastaOndeEstaPrograma;

    }


    // Senão, procura "Hora Atividade" dentro da mesma pasta.
    const filhas =
      pastaOndeEstaPrograma
        .getFoldersByName(
          NOME_PASTA_RAIZ_HORA_ATIVIDADE
        );


    if (filhas.hasNext()) {

      return filhas.next();

    }


    // Se não encontrou, cria dentro da pasta onde está o programa.
    return pastaOndeEstaPrograma
      .createFolder(
        NOME_PASTA_RAIZ_HORA_ATIVIDADE
      );

  }


  // Se a planilha-base estiver diretamente no Meu Drive,
  // procura/cria "Hora Atividade" no Meu Drive.
  const raiz =
    DriveApp.getRootFolder();


  const existentes =
    raiz.getFoldersByName(
      NOME_PASTA_RAIZ_HORA_ATIVIDADE
    );


  if (existentes.hasNext()) {

    return existentes.next();

  }


  return raiz.createFolder(
    NOME_PASTA_RAIZ_HORA_ATIVIDADE
  );

}


function nomeSeguroPasta_(
  nome
) {

  return String(
    nome || ""
  )
    .replace(
      /[\/\\]/g,
      "-"
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

}


function obterOuCriarPastaUnidade_(
  unidadeId
) {

  const unidade =
    buscarUnidadePorId_(
      unidadeId
    );


  if (!unidade) {

    throw new Error(
      "Unidade escolar não encontrada."
    );

  }


  const pastaRaiz =
    obterPastaRaizHoraAtividade_();


  const nomePasta =
    nomeSeguroPasta_(
      unidade.nome
    );


  const existentes =
    pastaRaiz.getFoldersByName(
      nomePasta
    );


  if (existentes.hasNext()) {

    return existentes.next();

  }


  return pastaRaiz.createFolder(
    nomePasta
  );

}


function obterOuCriarPastaAnoUnidade_(
  unidadeId,
  ano
) {

  const pastaUnidade =
    obterOuCriarPastaUnidade_(
      unidadeId
    );


  const nomePasta =
    String(
      ano
    );


  const existentes =
    pastaUnidade.getFoldersByName(
      nomePasta
    );


  if (existentes.hasNext()) {

    return existentes.next();

  }


  return pastaUnidade.createFolder(
    nomePasta
  );

}


// Mantida por compatibilidade com partes antigas do projeto.
// Novas planilhas de professor usam a estrutura Unidade > Ano.
function obterOuCriarPastaAno_(
  ano
) {

  const pastaRaiz =
    obterPastaRaizHoraAtividade_();


  const nomePasta =
    PREFIXO_PASTA_ANO_HORA_ATIVIDADE +
    String(ano);


  const existentes =
    pastaRaiz.getFoldersByName(
      nomePasta
    );


  if (existentes.hasNext()) {

    return existentes.next();

  }


  return pastaRaiz.createFolder(
    nomePasta
  );

}


function criarPastasDasUnidades_() {

  garantirEstruturaMunicipal_();


  const ss =
    getPlanilhaBase();


  const aba =
    ss.getSheetByName(
      ABA_UNIDADES
    );


  if (
    !aba ||
    aba.getLastRow() < 2
  ) {

    return {
      criadasOuVerificadas: 0
    };

  }


  const dados =
    aba
      .getRange(
        2,
        1,
        aba.getLastRow() - 1,
        4
      )
      .getValues();


  let quantidade = 0;


  dados.forEach(
    function(linha) {

      const id =
        linha[0];

      const ativo =
        String(
          linha[3] || ""
        )
          .trim()
          .toUpperCase();


      if (
        id &&
        ativo === "SIM"
      ) {

        obterOuCriarPastaUnidade_(
          id
        );

        quantidade++;

      }

    }
  );


  return {
    criadasOuVerificadas:
      quantidade
  };

}


// ==========================================================
// LOCALIZA UMA PLANILHA ATUAL PARA USAR COMO MODELO
// ==========================================================

function obterArquivoModeloProfessor_() {

  const ss =
    getPlanilhaBase();


  const aba =
    ss.getSheetByName(
      ABA_PROFESSORES
    );


  if (!aba) {

    throw new Error(
      "Aba PROFESSORES não encontrada."
    );

  }


  const ultimaLinha =
    aba.getLastRow();


  if (ultimaLinha < 2) {

    throw new Error(
      "Ainda não existe nenhuma planilha de professor para usar como modelo."
    );

  }


  const dados =
    aba
      .getRange(
        2,
        1,
        ultimaLinha - 1,
        4
      )
      .getValues();


  for (
    let i = 0;
    i < dados.length;
    i++
  ) {

    const planilhaId =
      String(
        dados[i][2] || ""
      ).trim();


    const ativo =
      String(
        dados[i][3] || ""
      )
        .trim()
        .toUpperCase();


    if (
      !planilhaId ||
      ativo !== "SIM"
    ) {
      continue;
    }


    try {

      const arquivo =
        DriveApp.getFileById(
          planilhaId
        );


      SpreadsheetApp
        .openById(
          planilhaId
        )
        .getName();


      return arquivo;


    } catch (erro) {

    }

  }


  throw new Error(
    "Não encontrei uma planilha ativa que possa ser usada como modelo."
  );

}


// ==========================================================
// MODELO INTERNO PORTÁTIL
//
// As abas-modelo ficam ocultas dentro da própria planilha-base.
// Assim, quando a planilha do aplicativo é copiada para outro
// Drive, o modelo das planilhas dos professores vai junto.
// ==========================================================

function garantirModeloInternoProfessor_() {

  const base =
    getPlanilhaBase();


  const faltantes =
    MESES_HORA_ATIVIDADE
      .filter(
        function(mes) {

          return !base.getSheetByName(
            PREFIXO_ABA_MODELO +
            mes
          );

        }
      );


  if (
    faltantes.length === 0
  ) {

    return {
      sucesso: true,
      criado: false
    };

  }


  const arquivoModelo =
    obterArquivoModeloProfessor_();


  const modelo =
    SpreadsheetApp.openById(
      arquivoModelo.getId()
    );


  faltantes.forEach(
    function(mes) {

      const origem =
        localizarAbaMes(
          modelo,
          mes
        );


      if (!origem) {

        throw new Error(
          "A planilha-modelo não possui a aba " +
          mes +
          "."
        );

      }


      const copia =
        origem.copyTo(
          base
        );


      copia.setName(
        PREFIXO_ABA_MODELO +
        mes
      );


      copia.hideSheet();

    }
  );


  SpreadsheetApp.flush();


  return {
    sucesso: true,
    criado: true
  };

}


function criarArquivoProfessorAPartirModeloInterno_(
  nomeArquivo,
  pastaDestino
) {

  garantirModeloInternoProfessor_();


  const base =
    getPlanilhaBase();


  const novo =
    SpreadsheetApp.create(
      nomeArquivo
    );


  const arquivoNovo =
    DriveApp.getFileById(
      novo.getId()
    );


  arquivoNovo.moveTo(
    pastaDestino
  );


  const abaInicial =
    novo.getSheets()[0];


  MESES_HORA_ATIVIDADE
    .forEach(
      function(mes) {

        const modelo =
          base.getSheetByName(
            PREFIXO_ABA_MODELO +
            mes
          );


        if (!modelo) {

          throw new Error(
            "Modelo interno ausente para " +
            mes +
            ". Execute instalarSistemaHoraAtividade()."
          );

        }


        const novaAba =
          modelo.copyTo(
            novo
          );


        novaAba.setName(
          mes
        );


        novaAba.showSheet();

      }
    );


  if (
    abaInicial &&
    novo.getSheets().length > 1
  ) {

    novo.deleteSheet(
      abaInicial
    );

  }


  SpreadsheetApp.flush();


  return arquivoNovo;

}


// ==========================================================
// LIMPA UMA CÓPIA PARA USO EM NOVO PROFESSOR / NOVO ANO
// ==========================================================

function prepararPlanilhaProfessor_(
  planilhaId,
  nomeProfessor
) {

  const ss =
    SpreadsheetApp.openById(
      planilhaId
    );


  MESES_HORA_ATIVIDADE
    .forEach(
      function(mes) {

        const aba =
          localizarAbaMes(
            ss,
            mes
          );


        if (!aba) {
          return;
        }


        // B10 no arquivo original possui uma validação com a lista
        // de professores da escola. Ao criar uma cópia para um novo
        // professor, removemos somente essa validação antes de gravar
        // o nome. A formatação da célula é preservada.
        const celulaNome =
          aba.getRange("B10");

        celulaNome
          .clearDataValidations();

        celulaNome
          .setValue(
            nomeProfessor
          );


        aba
          .getRange(
            LINHA_INICIAL_REGISTROS,
            1,
            LINHA_FINAL_REGISTROS -
              LINHA_INICIAL_REGISTROS +
              1,
            2
          )
          .clearContent();


        aba
          .getRange(
            LINHA_INICIAL_REGISTROS,
            4,
            LINHA_FINAL_REGISTROS -
              LINHA_INICIAL_REGISTROS +
              1,
            5
          )
          .clearContent();


        aba
          .getRange(
            LINHA_INICIAL_REGISTROS,
            9,
            LINHA_FINAL_REGISTROS -
              LINHA_INICIAL_REGISTROS +
              1,
            1
          )
          .clearContent();

      }
    );


  SpreadsheetApp.flush();


  return ss;

}


// ==========================================================
// CRIA A PLANILHA DE UM NOVO PROFESSOR AUTOMATICAMENTE
// ==========================================================

function criarPlanilhaProfessorAutomaticamente_(
  nomeProfessor,
  unidadeId
) {

  nomeProfessor =
    String(
      nomeProfessor || ""
    ).trim();


  if (!nomeProfessor) {

    throw new Error(
      "Nome do professor inválido."
    );

  }


  const ano =
    obterAnoAtual_();


  const unidade =
    buscarUnidadePorId_(
      unidadeId
    );


  if (
    !unidade ||
    unidade.ativo !== "SIM"
  ) {

    throw new Error(
      "Unidade escolar inválida ou inativa."
    );

  }


  const pastaAno =
    obterOuCriarPastaAnoUnidade_(
      unidadeId,
      ano
    );


  const nomeArquivo =
    nomeProfessor +
    " - Hora-Atividade " +
    ano;


  const existentes =
    pastaAno.getFilesByName(
      nomeArquivo
    );


  if (existentes.hasNext()) {

    throw new Error(
      "Já existe uma planilha para " +
      nomeProfessor +
      " em " +
      ano +
      "."
    );

  }


  const arquivoNovo =
    criarArquivoProfessorAPartirModeloInterno_(
      nomeArquivo,
      pastaAno
    );


  try {

    prepararPlanilhaProfessor_(
      arquivoNovo.getId(),
      nomeProfessor
    );


    return {

      arquivo:
        arquivoNovo,

      planilhaId:
        arquivoNovo.getId(),

      url:
        arquivoNovo.getUrl(),

      pastaId:
        pastaAno.getId()

    };


  } catch (erro) {

    try {
      arquivoNovo.setTrashed(true);
    } catch (e) {
    }

    throw erro;

  }

}


