// ==========================================================
// VERIFICA SE HOUVE VIRADA DE ANO
// ==========================================================
//
// Na primeira execução apenas grava o ano atual.
// A partir daí, quando detectar um ano diferente,
// executa a criação das novas planilhas.
//
function verificarViradaDeAno() {

  const lock =
    LockService.getScriptLock();


  try {

    lock.waitLock(
      30000
    );


    const propriedades =
      PropertiesService
        .getScriptProperties();


    const anoAtual =
      obterAnoAtual_();


    const anoRegistrado =
      Number(
        propriedades.getProperty(
          CHAVE_ANO_ATUAL_AUTOMACAO
        ) || 0
      );


    // Primeira instalação: não duplica nada.
    if (!anoRegistrado) {

      propriedades.setProperty(
        CHAVE_ANO_ATUAL_AUTOMACAO,
        String(anoAtual)
      );


      return {

        sucesso: true,
        criado: false,
        mensagem:
          "Automação anual inicializada para " +
          anoAtual +
          "."

      };

    }


    if (anoRegistrado === anoAtual) {

      return {

        sucesso: true,
        criado: false,
        mensagem:
          "O ano " +
          anoAtual +
          " já está configurado."

      };

    }


    const resultado =
      criarPlanilhasNovoAno_(
        anoAtual
      );


    propriedades.setProperty(
      CHAVE_ANO_ATUAL_AUTOMACAO,
      String(anoAtual)
    );


    return resultado;


  } finally {

    try {
      lock.releaseLock();
    } catch (e) {
    }

  }

}


// ==========================================================
// CRIA A PASTA E AS PLANILHAS DO NOVO ANO
// ==========================================================

function criarPlanilhasNovoAno_(
  anoNovo
) {

  const ss =
    getPlanilhaBase();


  const abaProf =
    ss.getSheetByName(
      ABA_PROFESSORES
    );


  if (!abaProf) {

    throw new Error(
      "Aba PROFESSORES não encontrada."
    );

  }


  const ultimaLinha =
    abaProf.getLastRow();


  if (ultimaLinha < 2) {

    return {

      sucesso: true,
      criado: false,
      mensagem:
        "Não existem professores cadastrados."

    };

  }


  const dados =
    abaProf
      .getRange(
        2,
        1,
        ultimaLinha - 1,
        5
      )
      .getValues();


  let criadas = 0;


  for (
    let i = 0;
    i < dados.length;
    i++
  ) {

    const linhaPlanilha =
      i + 2;


    const professorId =
      dados[i][0];


    const nome =
      String(
        dados[i][1] || ""
      ).trim();


    const planilhaIdAntiga =
      String(
        dados[i][2] || ""
      ).trim();


    const ativo =
      String(
        dados[i][3] || ""
      )
        .trim()
        .toUpperCase();


    const unidadeId =
      dados[i][4];


    if (
      !professorId ||
      !nome ||
      !planilhaIdAntiga ||
      !unidadeId ||
      ativo !== "SIM"
    ) {
      continue;
    }


    const arquivoAntigo =
      DriveApp.getFileById(
        planilhaIdAntiga
      );


    const nomeNovo =
      nome +
      " - Hora-Atividade " +
      anoNovo;


    const pastaNovoAno =
      obterOuCriarPastaAnoUnidade_(
        unidadeId,
        anoNovo
      );


    // Evita duplicação se uma execução anterior tiver
    // criado o arquivo antes de ser interrompida.
    const existentes =
      pastaNovoAno
        .getFilesByName(
          nomeNovo
        );


    let arquivoNovo;


    if (existentes.hasNext()) {

      arquivoNovo =
        existentes.next();

    } else {

      arquivoNovo =
        arquivoAntigo.makeCopy(
          nomeNovo,
          pastaNovoAno
        );

    }


    prepararPlanilhaProfessor_(
      arquivoNovo.getId(),
      nome
    );


    // Atualiza o ID usado pelo sistema.
    abaProf
      .getRange(
        linhaPlanilha,
        3
      )
      .setValue(
        arquivoNovo.getId()
      );


    registrarHistoricoPlanilha_(
      professorId,
      nome,
      anoNovo,
      arquivoNovo.getId(),
      "VIRADA_ANUAL"
    );


    criadas++;

  }


  SpreadsheetApp.flush();


  registrarLog(

    "SISTEMA",

    "VIRADA_ANUAL",

    "Ano " +
    anoNovo +
    " criado. Planilhas atualizadas: " +
    criadas

  );


  return {

    sucesso: true,
    criado: true,
    ano:
      anoNovo,
    quantidade:
      criadas,
    pastaId:
      obterPastaRaizHoraAtividade_().getId(),
    mensagem:
      "Ano " +
      anoNovo +
      " criado com sucesso. " +
      criadas +
      " planilha(s) preparada(s)."

  };

}


