// ==========================================================
// INSTALA O GATILHO AUTOMÁTICO
//
// EXECUTAR UMA ÚNICA VEZ MANUALMENTE.
// O gatilho roda diariamente por volta das 2h e só cria
// arquivos quando detectar mudança de ano.
// ==========================================================

function instalarAutomacaoViradaAnual() {

  const propriedades =
    PropertiesService
      .getScriptProperties();


  propriedades.setProperty(
    CHAVE_ANO_ATUAL_AUTOMACAO,
    String(
      obterAnoAtual_()
    )
  );


  const nomeFuncao =
    "verificarViradaDeAno";


  ScriptApp
    .getProjectTriggers()
    .forEach(
      function(gatilho) {

        if (
          gatilho.getHandlerFunction() ===
          nomeFuncao
        ) {

          ScriptApp.deleteTrigger(
            gatilho
          );

        }

      }
    );


  ScriptApp
    .newTrigger(
      nomeFuncao
    )
    .timeBased()
    .everyDays(1)
    .atHour(2)
    .create();


  return {
    sucesso: true,
    mensagem:
      "Automação anual instalada. O sistema verificará diariamente se houve mudança de ano."
  };

}


