// ==========================================================
// PAINEL ADMINISTRATIVO - RESUMO
// ==========================================================

function obterResumoAdmin(
  token,
  unidadeId
) {

  try {

    const sessao =
      validarSessao(
        token
      );

    const unidade =
      obterUnidadePermitida_(
        sessao,
        unidadeId
      );

    const ss =
      getPlanilhaBase();

    const aba =
      ss.getSheetByName(
        ABA_PROFESSORES
      );

    if (!aba) {
      throw new Error(
        "Aba PROFESSORES não encontrada."
      );
    }

    const professores = [];
    const totais = {};

    MESES_HORA_ATIVIDADE
      .forEach(
        function(mes) {
          totais[mes] = 0;
        }
      );

    let totalGeral = 0;

    if (
      aba.getLastRow() >= 2
    ) {

      const dados =
        aba
          .getRange(
            2,
            1,
            aba.getLastRow() - 1,
            5
          )
          .getValues();

      dados.forEach(
        function(linha) {

          const id = linha[0];
          const nome =
            String(linha[1] || "")
              .trim();
          const planilhaId =
            String(linha[2] || "")
              .trim();
          const ativo =
            String(linha[3] || "")
              .trim()
              .toUpperCase();
          const unidadeProfessor =
            linha[4];

          if (
            !id ||
            !nome ||
            ativo !== "SIM" ||
            String(
              unidadeProfessor
            ) !==
            String(
              unidade.id
            )
          ) {
            return;
          }

          const item = {
            id: id,
            nome: nome,
            unidadeId:
              unidadeProfessor,
            meses: [],
            totalAno: 0,
            erro: ""
          };

          try {

            const planilha =
              SpreadsheetApp.openById(
                planilhaId
              );

            MESES_HORA_ATIVIDADE
              .forEach(
                function(mes) {

                  const abaMes =
                    localizarAbaMes(
                      planilha,
                      mes
                    );

                  const minutos =
                    abaMes
                      ?
                      lerNumeroSeguro(
                        abaMes
                          .getRange("B57")
                          .getValue()
                      )
                      :
                      0;

                  item.meses.push({
                    mes: mes,
                    totalMinutos:
                      minutos,
                    existe:
                      Boolean(abaMes)
                  });

                  item.totalAno +=
                    minutos;

                  totais[mes] +=
                    minutos;

                  totalGeral +=
                    minutos;

                }
              );

          } catch (erro) {

            item.erro =
              "Não foi possível acessar a planilha.";

            MESES_HORA_ATIVIDADE
              .forEach(
                function(mes) {
                  item.meses.push({
                    mes: mes,
                    totalMinutos: 0,
                    existe: false
                  });
                }
              );

          }

          professores.push(
            item
          );

        }
      );

    }

    professores.sort(
      function(a, b) {
        return a.nome.localeCompare(
          b.nome,
          "pt-BR"
        );
      }
    );

    return {
      sucesso: true,
      unidade: unidade,
      professores: professores,
      totaisMeses:
        MESES_HORA_ATIVIDADE.map(
          function(mes) {
            return {
              mes: mes,
              totalMinutos:
                totais[mes]
            };
          }
        ),
      totalGeral:
        totalGeral
    };

  } catch (erro) {

    Logger.log(
      "obterResumoAdmin: " +
      erro.stack
    );

    return {
      sucesso: false,
      mensagem:
        erro.message
    };

  }

}


// ==========================================================
// ADMIN - DETALHES DE UM MÊS DE UM PROFESSOR
// SOMENTE LEITURA
// ==========================================================

function obterMesProfessorAdmin(token, professorId, mes) {

  try {

    const sessao = validarSessao(token);

    if (
      !sessao.valido ||
      !["ADMIN", "DIRETOR"]
        .includes(
          sessao.usuario.tipo
        )
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }

    const professor = buscarProfessorPorId(professorId);

    if (!professor) {
      throw new Error(
        "Professor não encontrado."
      );
    }

    if (
      sessao.usuario.tipo ===
        "DIRETOR" &&
      String(
        professor.unidadeId
      ) !==
      String(
        sessao.usuario.unidadeId
      )
    ) {
      throw new Error(
        "Acesso não autorizado a este professor."
      );
    }

    mes = normalizarMesHoraAtividade(mes);

    if (!MESES_HORA_ATIVIDADE.includes(mes)) {
      throw new Error("Mês inválido.");
    }

    const planilha = SpreadsheetApp.openById(professor.planilhaId);
    const aba = localizarAbaMes(planilha, mes);

    if (!aba) {
      throw new Error("Aba do mês não encontrada.");
    }

    const quantidade =
      LINHA_FINAL_REGISTROS -
      LINHA_INICIAL_REGISTROS +
      1;

    const valores = aba
      .getRange(
        LINHA_INICIAL_REGISTROS,
        1,
        quantidade,
        9
      )
      .getValues();

    const exibidos = aba
      .getRange(
        LINHA_INICIAL_REGISTROS,
        1,
        quantidade,
        9
      )
      .getDisplayValues();

    const registros = [];

    for (let i = 0; i < quantidade; i++) {

      const data = valores[i][0];
      const minutos = lerNumeroSeguro(valores[i][1]);
      const atividade = String(exibidos[i][3] || "").trim();
      const observacao = String(exibidos[i][8] || "").trim();

      if (!data && !minutos && !atividade && !observacao) {
        continue;
      }

      registros.push({
        linha: LINHA_INICIAL_REGISTROS + i,
        data: formatarDataParaTela(data, aba),
        minutos: minutos,
        atividade: atividade,
        observacao: observacao
      });

    }

    return {
      sucesso: true,
      professor: {
        id: professor.id,
        nome: professor.nome
      },
      mes: mes,
      totalMinutos: lerNumeroSeguro(
        aba.getRange("B57").getValue()
      ),
      registros: registros
    };

  } catch (erro) {

    Logger.log("obterMesProfessorAdmin: " + erro.stack);

    return {
      sucesso: false,
      mensagem: erro.message
    };

  }

}


