function listarUsuariosPorTipo(
  token,
  tipoSolicitado,
  unidadeId
) {

  try {

    const sessao =
      validarSessao(
        token
      );

    if (
      !sessao.valido ||
      !["ADMIN", "DIRETOR"]
        .includes(
          sessao.usuario.tipo
        )
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }


    tipoSolicitado =
      String(
        tipoSolicitado || ""
      )
        .trim()
        .toUpperCase();


    if (
      !["DIRETOR", "PROFESSOR"]
        .includes(
          tipoSolicitado
        )
    ) {
      throw new Error(
        "Tipo de usuário inválido."
      );
    }


    // Diretor não pode consultar diretores.
    if (
      sessao.usuario.tipo ===
        "DIRETOR" &&
      tipoSolicitado !==
        "PROFESSOR"
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }


    if (
      sessao.usuario.tipo ===
        "DIRETOR"
    ) {

      unidadeId =
        sessao.usuario.unidadeId;

    }


    garantirEstruturaMunicipal_();


    const ss =
      getPlanilhaBase();


    const abaUsuarios =
      ss.getSheetByName(
        ABA_USUARIOS
      );


    if (!abaUsuarios) {
      throw new Error(
        "Aba USUÁRIOS não encontrada."
      );
    }


    // Mapa ID -> nome da unidade.
    const abaUnidades =
      ss.getSheetByName(
        ABA_UNIDADES
      );


    const mapaUnidades =
      {};


    if (
      abaUnidades &&
      abaUnidades.getLastRow() >= 2
    ) {

      abaUnidades
        .getRange(
          2,
          1,
          abaUnidades.getLastRow() - 1,
          4
        )
        .getValues()
        .forEach(
          function(linha) {

            mapaUnidades[
              String(linha[0])
            ] =
              String(
                linha[2] || ""
              );

          }
        );

    }


    if (
      abaUsuarios.getLastRow() < 2
    ) {

      return {
        sucesso: true,
        usuarios: []
      };

    }


    const dados =
      abaUsuarios
        .getRange(
          2,
          1,
          abaUsuarios.getLastRow() - 1,
          10
        )
        .getValues();


    const usuarios =
      dados
        .filter(
          function(linha) {

            const tipo =
              String(
                linha[4] || ""
              )
                .trim()
                .toUpperCase();


            const unidadeUsuario =
              String(
                linha[9] || ""
              );


            if (
              tipo !==
              tipoSolicitado
            ) {
              return false;
            }


            // Se unidade foi escolhida, filtra por ela.
            if (
              unidadeId &&
              String(unidadeId) !==
              unidadeUsuario
            ) {
              return false;
            }


            return true;

          }
        )
        .map(
          function(linha) {

            const unidadeUsuario =
              String(
                linha[9] || ""
              );


            return {

              id:
                linha[0],

              nome:
                String(
                  linha[1] || ""
                ),

              login:
                String(
                  linha[2] || ""
                ),

              tipo:
                String(
                  linha[4] || ""
                )
                  .trim()
                  .toUpperCase(),

              professorId:
                linha[5],

              ativo:
                String(
                  linha[6] || ""
                )
                  .trim()
                  .toUpperCase(),

              email:
                String(
                  linha[7] || ""
                ),

              unidadeId:
                linha[9],

              unidadeNome:
                mapaUnidades[
                  unidadeUsuario
                ] ||
                ""

            };

          }
        );


    usuarios.sort(
      function(a, b) {

        return String(
          a.nome || ""
        )
          .localeCompare(
            String(
              b.nome || ""
            ),
            "pt-BR",
            {
              sensitivity:
                "base"
            }
          );

      }
    );


    return {

      sucesso:
        true,

      usuarioLogadoId:
        sessao.usuario.id,

      usuarios:
        usuarios

    };


  } catch (erro) {

    return {

      sucesso:
        false,

      mensagem:
        erro.message

    };

  }

}


function listarUsuariosAdmin(
  token,
  unidadeId
) {

  try {

    const sessao =
      validarSessao(
        token
      );

    const unidade =
      obterUnidadePermitida_(
        sessao,
        unidadeId
      );

    const ss =
      getPlanilhaBase();

    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );

    if (!aba) {
      throw new Error(
        "Aba USUÁRIOS não encontrada."
      );
    }

    if (
      aba.getLastRow() < 2
    ) {
      return {
        sucesso: true,
        unidade: unidade,
        usuarioLogadoId:
          sessao.usuario.id,
        usuarios: []
      };
    }

    const dados =
      aba
        .getRange(
          2,
          1,
          aba.getLastRow() - 1,
          10
        )
        .getValues();

    let usuarios =
      dados
        .filter(
          function(linha) {

            const tipo =
              String(
                linha[4] || ""
              )
                .trim()
                .toUpperCase();

            const mesmaUnidade =
              String(linha[9]) ===
              String(unidade.id);

            if (
              sessao.usuario.tipo ===
              "DIRETOR"
            ) {
              return (
                mesmaUnidade &&
                tipo === "PROFESSOR"
              );
            }

            return (
              mesmaUnidade &&
              ["PROFESSOR", "DIRETOR"]
                .includes(tipo)
            );

          }
        )
        .map(
          function(linha) {
            return {
              id: linha[0],
              nome:
                String(linha[1] || ""),
              login:
                String(linha[2] || ""),
              tipo:
                String(linha[4] || "")
                  .toUpperCase(),
              professorId:
                linha[5],
              ativo:
                String(linha[6] || "")
                  .toUpperCase(),
              email:
                String(linha[7] || ""),
              unidadeId:
                linha[9]
            };
          }
        );

    usuarios.sort(
      function(a, b) {
        if (a.tipo !== b.tipo) {
          return a.tipo ===
            "DIRETOR"
              ? -1
              : 1;
        }
        return a.nome.localeCompare(
          b.nome,
          "pt-BR"
        );
      }
    );

    return {
      sucesso: true,
      unidade: unidade,
      usuarioLogadoId:
        sessao.usuario.id,
      usuarios: usuarios
    };

  } catch (erro) {

    return {
      sucesso: false,
      mensagem:
        erro.message
    };

  }

}


function cadastrarDiretor(
  token,
  nome,
  login,
  senha,
  email,
  unidadeId
) {

  try {

    const sessao =
      validarSessao(
        token
      );

    if (
      !sessao.valido ||
      sessao.usuario.tipo !==
        "ADMIN"
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }

    const unidade =
      buscarUnidadePorId_(
        unidadeId
      );

    if (
      !unidade ||
      unidade.ativo !== "SIM"
    ) {
      throw new Error(
        "Selecione uma unidade escolar válida."
      );
    }

    nome =
      String(nome || "")
        .trim();

    login =
      String(login || "")
        .trim()
        .toLowerCase();

    senha =
      String(senha || "");

    email =
      String(email || "")
        .trim()
        .toLowerCase();

    if (
      !nome ||
      !login ||
      !senha ||
      !email
    ) {
      throw new Error(
        "Preencha nome, login, e-mail e senha."
      );
    }

    if (
      !emailValido_(email)
    ) {
      throw new Error(
        "Informe um e-mail válido."
      );
    }

    if (
      emailExiste_(email)
    ) {
      throw new Error(
        "Este e-mail já está vinculado a outro usuário."
      );
    }

    if (
      senha.length < 6
    ) {
      throw new Error(
        "A senha deve ter pelo menos 6 caracteres."
      );
    }

    if (
      loginExiste(login)
    ) {
      throw new Error(
        "Este login já está cadastrado."
      );
    }

    const ss =
      getPlanilhaBase();

    const aba =
      ss.getSheetByName(
        ABA_USUARIOS
      );

    const id =
      gerarProximoId(
        ABA_USUARIOS
      );

    aba.appendRow([
      id,
      nome,
      login,
      gerarHashSenha(senha),
      "DIRETOR",
      "",
      "SIM",
      email,
      "NÃO",
      unidade.id
    ]);

    registrarLog(
      sessao.usuario.login,
      "CADASTRAR_DIRETOR",
      "Diretor cadastrado: " +
      nome +
      " | " +
      unidade.nome
    );

    return {
      sucesso: true,
      mensagem:
        "Diretor cadastrado com sucesso."
    };

  } catch (erro) {

    return {
      sucesso: false,
      mensagem:
        erro.message
    };

  }

}


function cadastrarAdministrador(token, nome, login, senha, email) {

  try {

    const sessao = validarSessao(token);

    if (
      !sessao.valido ||
      sessao.usuario.tipo !== "ADMIN"
    ) {
      throw new Error("Acesso não autorizado.");
    }

    nome = String(nome || "").trim();
    login = String(login || "").trim().toLowerCase();
    senha = String(senha || "");
    email = String(email || "").trim().toLowerCase();

    if (!nome || !login || !senha || !email) {
      throw new Error("Preencha nome, login, e-mail e senha.");
    }

    if (!emailValido_(email)) {
      throw new Error("Informe um e-mail válido.");
    }

    if (emailExiste_(email)) {
      throw new Error("Este e-mail já está vinculado a outro usuário.");
    }

    if (senha.length < 6) {
      throw new Error("A senha deve ter pelo menos 6 caracteres.");
    }

    if (loginExiste(login)) {
      throw new Error("Este login já está cadastrado.");
    }

    const ss = getPlanilhaBase();
    const aba = ss.getSheetByName(ABA_USUARIOS);
    const id = gerarProximoId(ABA_USUARIOS);

    aba.appendRow([
      id,
      nome,
      login,
      gerarHashSenha(senha),
      "ADMIN",
      "",
      "SIM",
      email,
      "NÃO",
      ""
    ]);

    registrarLog(
      sessao.usuario.login,
      "CADASTRAR_ADMIN",
      "Administrador cadastrado: " + nome + " | login: " + login
    );

    return {
      sucesso: true,
      mensagem: "Administrador cadastrado com sucesso."
    };

  } catch (erro) {

    return {
      sucesso: false,
      mensagem: erro.message
    };

  }

}


function redefinirSenhaUsuarioAdmin(token, usuarioId, novaSenha) {

  try {

    const sessao = validarSessao(token);

    if (
      !sessao.valido ||
      !["ADMIN", "DIRETOR"]
        .includes(
          sessao.usuario.tipo
        )
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }

    novaSenha = String(novaSenha || "");

    if (novaSenha.length < 6) {
      throw new Error("A senha deve ter pelo menos 6 caracteres.");
    }

    const ss = getPlanilhaBase();
    const aba = ss.getSheetByName(ABA_USUARIOS);
    const ultimaLinha = aba.getLastRow();

    for (let linha = 2; linha <= ultimaLinha; linha++) {

      const id = aba.getRange(linha, 1).getValue();

      if (String(id) === String(usuarioId)) {

        if (
          sessao.usuario.tipo ===
          "DIRETOR"
        ) {

          const tipoAlvo =
            String(
              aba.getRange(
                linha,
                5
              ).getValue() || ""
            )
              .trim()
              .toUpperCase();

          const unidadeAlvo =
            aba.getRange(
              linha,
              COL_USUARIO_UNIDADE_ID
            ).getValue();

          if (
            tipoAlvo !== "PROFESSOR" ||
            String(unidadeAlvo) !==
            String(
              sessao.usuario.unidadeId
            )
          ) {
            throw new Error(
              "Acesso não autorizado a este usuário."
            );
          }

        }

        const nome = String(
          aba.getRange(linha, 2).getValue() || ""
        );

        aba
          .getRange(linha, 4)
          .setValue(gerarHashSenha(novaSenha));

        registrarLog(
          sessao.usuario.login,
          "REDEFINIR_SENHA",
          "Senha redefinida para: " + nome
        );

        return {
          sucesso: true,
          mensagem: "Senha alterada com sucesso."
        };

      }

    }

    throw new Error("Usuário não encontrado.");

  } catch (erro) {

    return {
      sucesso: false,
      mensagem: erro.message
    };

  }

}


function alterarStatusUsuarioAdmin(token, usuarioId, novoStatus) {

  try {

    const sessao = validarSessao(token);

    if (
      !sessao.valido ||
      !["ADMIN", "DIRETOR"]
        .includes(
          sessao.usuario.tipo
        )
    ) {
      throw new Error(
        "Acesso não autorizado."
      );
    }

    if (String(usuarioId) === String(sessao.usuario.id)) {
      throw new Error("Você não pode desativar o usuário com o qual está conectado.");
    }

    novoStatus = String(novoStatus || "").trim().toUpperCase();

    if (!["SIM", "NÃO"].includes(novoStatus)) {
      throw new Error("Status inválido.");
    }

    const ss = getPlanilhaBase();
    const abaUsuarios = ss.getSheetByName(ABA_USUARIOS);
    const ultimaLinha = abaUsuarios.getLastRow();

    for (let linha = 2; linha <= ultimaLinha; linha++) {

      const id = abaUsuarios.getRange(linha, 1).getValue();

      if (String(id) !== String(usuarioId)) {
        continue;
      }

      if (
        sessao.usuario.tipo ===
        "DIRETOR"
      ) {

        const tipoAlvo =
          String(
            abaUsuarios
              .getRange(
                linha,
                5
              )
              .getValue() || ""
          )
            .trim()
            .toUpperCase();

        const unidadeAlvo =
          abaUsuarios
            .getRange(
              linha,
              COL_USUARIO_UNIDADE_ID
            )
            .getValue();

        if (
          tipoAlvo !== "PROFESSOR" ||
          String(unidadeAlvo) !==
          String(
            sessao.usuario.unidadeId
          )
        ) {
          throw new Error(
            "Acesso não autorizado a este usuário."
          );
        }

      }

      const nome = String(
        abaUsuarios.getRange(linha, 2).getValue() || ""
      );

      const tipo = String(
        abaUsuarios.getRange(linha, 5).getValue() || ""
      ).toUpperCase();

      const professorId = abaUsuarios
        .getRange(linha, 6)
        .getValue();

      abaUsuarios
        .getRange(linha, 7)
        .setValue(novoStatus);

      if (tipo === "PROFESSOR" && professorId) {

        const abaProf = ss.getSheetByName(ABA_PROFESSORES);

        if (abaProf) {

          const ultimaProf = abaProf.getLastRow();

          for (let lp = 2; lp <= ultimaProf; lp++) {

            const idProf = abaProf.getRange(lp, 1).getValue();

            if (String(idProf) === String(professorId)) {
              abaProf
                .getRange(lp, 4)
                .setValue(novoStatus);
              break;
            }

          }

        }

      }

      registrarLog(
        sessao.usuario.login,
        novoStatus === "SIM" ? "ATIVAR_USUARIO" : "DESATIVAR_USUARIO",
        nome + " | ID " + usuarioId
      );

      return {
        sucesso: true,
        mensagem:
          novoStatus === "SIM"
            ? "Usuário ativado."
            : "Usuário desativado."
      };

    }

    throw new Error("Usuário não encontrado.");

  } catch (erro) {

    return {
      sucesso: false,
      mensagem: erro.message
    };

  }

}


