function listarLogsAdmin(token, filtros) {

  try {

    const sessao = validarSessao(token);

    if (
      !sessao.valido ||
      sessao.usuario.tipo !== "ADMIN"
    ) {
      throw new Error("Acesso não autorizado.");
    }

    filtros = filtros || {};

    const filtroUsuario = String(filtros.usuario || "")
      .trim()
      .toLowerCase();

    const filtroAcao = String(filtros.acao || "")
      .trim()
      .toLowerCase();

    const inicio = converterDataFiltroAdmin(
      filtros.dataInicial,
      false
    );

    const fim = converterDataFiltroAdmin(
      filtros.dataFinal,
      true
    );

    const ss = getPlanilhaBase();
    const aba = ss.getSheetByName(ABA_LOGS);

    if (!aba) {
      throw new Error("Aba LOGS não encontrada.");
    }

    const ultimaLinha = aba.getLastRow();

    if (ultimaLinha < 2) {
      return {
        sucesso: true,
        logs: [],
        acoes: []
      };
    }

    const dados = aba
      .getRange(2, 1, ultimaLinha - 1, 4)
      .getValues();

    const timezone = ss.getSpreadsheetTimeZone();
    const conjuntoAcoes = {};
    const logs = [];

    for (let i = dados.length - 1; i >= 0; i--) {

      const linha = dados[i];
      const data = linha[0];
      const usuario = String(linha[1] || "");
      const acao = String(linha[2] || "");
      const detalhes = String(linha[3] || "");

      if (acao) {
        conjuntoAcoes[acao] = true;
      }

      if (
        filtroUsuario &&
        usuario.toLowerCase().indexOf(filtroUsuario) === -1
      ) {
        continue;
      }

      if (
        filtroAcao &&
        acao.toLowerCase() !== filtroAcao
      ) {
        continue;
      }

      if (data instanceof Date && !isNaN(data.getTime())) {

        if (inicio && data < inicio) {
          continue;
        }

        if (fim && data > fim) {
          continue;
        }

      }

      logs.push({
        dataHora:
          data instanceof Date && !isNaN(data.getTime())
            ? Utilities.formatDate(
                data,
                timezone,
                "dd/MM/yyyy HH:mm:ss"
              )
            : String(data || ""),
        usuario: usuario,
        acao: acao,
        detalhes: detalhes
      });

      if (logs.length >= 300) {
        break;
      }

    }

    return {
      sucesso: true,
      logs: logs,
      acoes: Object.keys(conjuntoAcoes).sort()
    };

  } catch (erro) {

    return {
      sucesso: false,
      mensagem: erro.message
    };

  }

}


function converterDataFiltroAdmin(texto, fimDoDia) {

  texto = String(texto || "").trim();

  if (!texto) {
    return null;
  }

  const partes = texto.split("-");

  if (partes.length !== 3) {
    return null;
  }

  const ano = Number(partes[0]);
  const mes = Number(partes[1]);
  const dia = Number(partes[2]);

  if (!ano || !mes || !dia) {
    return null;
  }

  return fimDoDia
    ? new Date(ano, mes - 1, dia, 23, 59, 59, 999)
    : new Date(ano, mes - 1, dia, 0, 0, 0, 0);

}
